var UNITE = { no: 10, ar: "الرِّفْقُ بِالحَيَوانِ", tr: "Kindness to Animals", pfx: "k3u10:",
  giris: "Unit 10: kindness to animals in Islam; animals' rights and excellence in slaughter. Grammar: specification (tamyīz); the generic negating lā. Spelling: the writing of hamzas (general review)." };
var DERSLER = [
// ---------------- DERS 64 ----------------
{ no: 64, kisa: "الرِّفْقُ بِالحَيَوانِ", ar: "الرِّفْقُ بِالحَيَوانِ", tr: "Kindness to Animals", ozet: "Reading text: mercy to animals, their rights, excellence in slaughter, endowments and examples from the Companions.", bloklar: [
 { t: "hazirlik", ar: "ما قَبْلَ القِراءَةِ", ogeler: [
  ["عِنْدَما تَقْرَأُ عُنْوانًا مِثْلَ «الرِّفْقُ بِالحَيَوانِ»، ما أَوَّلُ سُؤالٍ يَتَبادَرُ إِلى ذِهْنِكَ؟", "When you read a title like “Kindness to Animals,” what is the first question that comes to your mind?"], ["ما الحَيَواناتُ المَقْصودَةُ هُنا؟", "Which animals are meant here?"],
  ["ماذا تَتَوَقَّعُ أَنْ تَجِدَ في هذا النَّصِّ؟", "What do you expect to find in this text?"], ["هَلْ تَعْرِفُ قِصَّةً أَوْ حَديثًا عَنِ الرِّفْقِ بِالحَيَوانِ في الإِسْلامِ؟ اذْكُرْهُ.", "Do you know a story or hadith about kindness to animals in Islam? Tell it."],
  ["ما رَأْيُكَ في أُمَّةٍ تُبالِغُ في الرِّفْقِ بِالحَيَوانِ، وَلا تَهْتَمُّ بِحُقوقِ الإِنْسانِ؟", "What do you think of a nation that goes to extremes in kindness to animals and cares little for human rights?"],
  ["ما رَأْيُكَ في: مُصارَعَةِ الثّيرانِ؟ مُصارَعَةِ الدُّيوكِ؟ مُصارَعَةِ الجِمالِ؟ اتِّخاذِ الحَيَوانِ هَدَفًا لِلَّعِبِ؟", "What do you think of bullfighting, cockfighting, camel wrestling and taking an animal as a target for sport?"]] },
 { t: "metin", resim: ["ordek"], paragraf: [
  [["إِنَّ عالَمَ الحَيَوانِ كَعالَمِ الإِنْسانِ، لَهُ خَصائِصُهُ وَطَبائِعُهُ وَشُعورُهُ المُشابِهَةُ - في أَحْوالٍ كَثيرَةٍ - لِلْإِنْسانِ، قالَ تَعالى: ﴿وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ﴾.", "The world of animals is like the world of humans; in many respects it has its own characteristics, natures and feelings that resemble man's. God Almighty says: “There is no creature on the earth, nor a bird that flies with its two wings, but they are communities like you.”", "m64-0"],
   ["كَما أَنَّ رَحْمَةَ الإِنْسانِ لِلْحَيَوانِ قَدْ تُدْخِلُ صاحِبَها الجَنَّةَ، كَما قالَ الرَّسولُ ﷺ: «بَيْنَما رَجُلٌ يَمْشي بِطَريقٍ اشْتَدَّ عَلَيْهِ العَطَشُ، فَوَجَدَ بِئْرًا فَنَزَلَ فيها، فَشَرِبَ ثُمَّ خَرَجَ، فَإِذا كَلْبٌ يَلْهَثُ (يَأْكُلُ الثَّرى مِنَ العَطَشِ)، فَقالَ الرَّجُلُ: لَقَدْ بَلَغَ هذا الكَلْبَ مِنَ العَطَشِ مِثْلُ الَّذي كانَ بَلَغَ بي، فَنَزَلَ البِئْرَ فَمَلَأَ خُفَّهُ، ثُمَّ أَمْسَكَهُ بِفيهِ فَسَقى الكَلْبَ، فَشَكَرَ اللهُ لَهُ فَغَفَرَ لَهُ». قالوا: يا رَسولَ اللهِ، وَإِنَّ لَنا في البَهائِمِ أَجْرًا؟ فَقالَ: «نَعَمْ، في كُلِّ ذاتِ كَبِدٍ رَطْبَةٍ أَجْرٌ».", "A person's mercy to an animal may even admit its owner to Paradise; the Messenger of God ﷺ said: “A man was walking on a road when his thirst became severe; he found a well, went down into it, drank and came out. And there was a dog panting with its tongue out, licking the damp earth from thirst. The man said, ‘The thirst that reached me has reached this dog too’; he went down into the well, filled his leather sock, then held it in his mouth and gave the dog water. God thanked him for this and forgave him.” They said, “O Messenger of God, do we have reward in animals too?” He said, “Yes, in every living being with a moist liver there is reward.”", "m64-1"],
   ["كَما أَنَّ القَسْوَةَ عَلى الحَيَوانِ تُدْخِلُ النّارَ، كَما قالَ الرَّسولُ ﷺ: «دَخَلَتِ امْرَأَةٌ النّارَ في هِرَّةٍ رَبَطَتْها، فَلَمْ تُطْعِمْها، وَلَمْ تَدَعْها تَأْكُلُ مِنْ خَشاشِ الأَرْضِ».", "Harshness to an animal also admits to Hell; the Messenger of God ﷺ said: “A woman entered Hell because of a cat which she had tied up and neither fed nor let eat of the vermin of the earth.”", "m64-2"]],
  [["وَقَدْ سَخَّرَ اللهُ - تَعالى - كَثيرًا مِنَ الحَيَواناتِ لِخِدْمَةِ الإِنْسانِ. قالَ تَعالى: ﴿وَالْأَنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَ * وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ * وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَحِيمٌ * وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً وَيَخْلُقُ مَا لَا تَعْلَمُونَ﴾.", "God Almighty has placed many animals at man's service: “And He created the cattle; in them is warmth for you and benefits, and from them you eat. And in them is beauty for you when you bring them home in the evening and when you send them out to pasture in the morning. They carry your loads to a land you could not reach except with great hardship to yourselves; indeed your Lord is Kind, Merciful. And horses, mules and donkeys (He created) for you to ride and for adornment; and He creates what you do not know.”", "m64-3"],
   ["وَجاءَ الأَمْرُ بِالرِّفْقِ بِالحَيَوانِ، وَالنَّهْيُ عَنْ إِرْهاقِهِ؛ وَلِذا فَقَدْ نُهِيَ الإِنْسانُ عَنِ البَقاءِ طَويلًا عَلى ظَهْرِ الحَيَوانِ وَهُوَ واقِفٌ، فَقَدْ قالَ ﷺ: «إِيّاكُمْ أَنْ تَتَّخِذوا ظُهورَ دَوابِّكُمْ مَنابِرَ»، وَنَهى عَنْ تَحْميلِهِ أَكْثَرَ مِمّا يَسْتَطيعُ. وَوَضَعَتِ الشَّريعَةُ حُقوقًا لِلْحَيَوانِ، في حَقِّ مَنِ اسْتَأْجَرَهُ لِلْحَمْلِ أَوْ لِلرُّكوبِ فَحَمَّلَهُ أَكْثَرَ مِمّا يَسْتَطيعُ، فَأَلْزَمَتْهُ بِضَمانِ ثَمَنِهِ لِمالِكِهِ. وَلا تُساقُ الحَيَواناتُ سَوْقًا شَديدًا تَحْتَ الأَحْمالِ، وَلا تُضْرَبُ ضَرْبًا قَوِيًّا، وَلا توقَفُ في السّاحاتِ العامَّةِ وَعَلى ظُهورِها أَحْمالُها.", "Kindness to animals was commanded, and tiring them was forbidden. For this reason it was forbidden for a person to remain on an animal's back for a long time while it is standing; the Prophet ﷺ said: “Beware of making your animals' backs pulpits.” He also forbade loading an animal beyond its strength. The Sharia set down rights for animals: it made one who hires an animal for carrying or riding and loads it beyond its strength liable to pay its owner the animal's price. Animals are not to be driven harshly under load, beaten violently, or kept waiting in squares with their burdens on their backs.", "m64-4"]],
  [["وَتَنْهى الشَّريعَةُ عَنْ إِرْهاقِ الحَيَوانِ بِالعَمَلِ فَوْقَ ما يَسْتَطيعُ؛ فَعَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ قالَ: أَرْدَفَني رَسولُ اللهِ ﷺ خَلْفَهُ ذاتَ يَوْمٍ، فَأَسَرَّ إِلَيَّ حَديثًا لا أُحَدِّثُ بِهِ أَحَدًا مِنَ النّاسِ، وَكانَ أَحَبُّ ما اسْتَتَرَ بِهِ رَسولُ اللهِ ﷺ لِحاجَتِهِ هَدَفًا أَوْ حائِطَ نَخْلٍ. قالَ: فَدَخَلَ حائِطًا لِرَجُلٍ مِنَ الأَنْصارِ، فَإِذا جَمَلٌ، فَلَمّا رَأى النَّبِيَّ ﷺ حَنَّ وَذَرَفَتْ عَيْناهُ، فَأَتاهُ النَّبِيُّ ﷺ فَمَسَحَ ذِفْراهُ فَسَكَتَ، فَقالَ: «مَنْ رَبُّ هذا الجَمَلِ؟ لِمَنْ هذا الجَمَلُ؟» فَجاءَ فَتًى مِنَ الأَنْصارِ فَقالَ: لي يا رَسولَ اللهِ، فَقالَ: «أَفَلا تَتَّقي اللهَ في هذِهِ البَهيمَةِ الَّتي مَلَّكَكَ اللهُ إِيّاها، فَإِنَّهُ شَكا إِلَيَّ أَنَّكَ تُجيعُهُ وَتُدْئِبُهُ» (تُتْعِبُهُ بِكَثْرَةِ العَمَلِ).", "The Sharia forbids working an animal beyond its strength and wearing it out. ʿAbdullāh ibn Jaʿfar tells: One day the Messenger of God ﷺ took me up behind him and told me a secret that I will tell to no one. The cover the Messenger ﷺ liked best for relieving himself was a mound or a palm grove. He entered the garden of one of the Anṣār; and there was a camel! When the camel saw the Prophet ﷺ it groaned, and tears flowed from its eyes. The Prophet ﷺ came to it and stroked behind its ears; the camel fell silent. He said, “Who is the owner of this camel? Whose camel is this?” A young man of the Anṣār came and said, “Mine, O Messenger of God.” He said: “Do you not fear God concerning this animal which God has given you to own? It complained to me that you starve it and work it hard and tire it.”", "m64-5"],
   ["كَما تُحَرِّمُ الشَّريعَةُ أَنْ يُلْعَبَ بِالحَيَوانِ. قالَ الرَّسولُ ﷺ: «ما مِنْ إِنْسانٍ يَقْتُلُ عُصْفورًا فَما فَوْقَها بِغَيْرِ حَقِّها إِلّا سَأَلَهُ اللهُ عَنْها يَوْمَ القِيامَةِ». قيلَ: يا رَسولَ اللهِ، وَما حَقُّها؟ قالَ: «حَقُّها أَنْ يَذْبَحَها فَيَأْكُلَها، وَلا يَقْطَعَ رَأْسَها فَيَرْمِيَ بِهِ».", "The Sharia also forbids playing with an animal. The Messenger of God ﷺ said: “God will question on the Day of Resurrection every person who kills a sparrow or anything bigger without right.” It was said, “O Messenger of God, what is its right?” He said, “Its right is that he slaughter it and eat it, and not cut off its head and throw it away.”", "m64-6"],
   ["وَتُحَرِّمُ اتِّخاذَهُ هَدَفًا لِتَعْليمِ الإِصابَةِ؛ فَقَدْ مَرَّ ابْنُ عُمَرَ بِفِتْيانٍ مِنْ قُرَيْشٍ قَدْ نَصَبوا طَيْرًا وَهُمْ يَرْمونَهُ، وَقَدْ جَعَلوا لِصاحِبِ الطَّيْرِ كُلَّ خاطِئَةٍ مِنْ نَبْلِهِمْ، فَلَمّا رَأَوُا ابْنَ عُمَرَ تَفَرَّقوا، فَقالَ ابْنُ عُمَرَ: مَنْ فَعَلَ هذا؟ لَعَنَ اللهُ مَنْ فَعَلَ هذا، إِنَّ رَسولَ اللهِ ﷺ «لَعَنَ مَنِ اتَّخَذَ شَيْئًا فيهِ الرّوحُ غَرَضًا» (أَيْ هَدَفًا). وَتَنْهى الشَّريعَةُ عَنْ وَسْمِ الحَيَواناتِ في وُجوهِها بِالكَيِّ بِالنّارِ، فَعَنْ جابِرٍ أَنَّ النَّبِيَّ ﷺ مَرَّ عَلَيْهِ حِمارٌ قَدْ وُسِمَ في وَجْهِهِ، فَقالَ: «لَعَنَ اللهُ الَّذي وَسَمَهُ».", "It also forbids taking an animal as a target for learning archery: Ibn ʿUmar passed by some young men of Quraysh who had set up a bird and were shooting arrows at it; they had stipulated that every arrow that missed be given to the bird's owner. When they saw Ibn ʿUmar they dispersed. Ibn ʿUmar said: “Who did this? May God curse whoever did this! The Messenger of God ﷺ cursed whoever takes a living thing as a target.” The Sharia also forbids branding animals on the face with fire: according to Jābir's report a donkey branded on the face passed by the Prophet ﷺ; he said, “May God curse the one who branded it.”", "m64-7"]],
  [["أَمّا إِذا كانَ الحَيَوانُ مِمّا يُؤْكَلُ، فَإِنَّ الرَّحْمَةَ بِهِ أَنْ تُحَدَّ السِّكّينُ، وَيُسْقى الماءَ، وَيُراحَ بَعْدَ الذَّبْحِ قَبْلَ السَّلْخِ. قالَ رَسولُ اللهِ ﷺ: «إِنَّ اللهَ كَتَبَ الإِحْسانَ عَلى كُلِّ شَيْءٍ، فَإِذا قَتَلْتُمْ فَأَحْسِنوا القِتْلَةَ، وَإِذا ذَبَحْتُمْ فَأَحْسِنوا الذَّبْحَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، فَلْيُرِحْ ذَبيحَتَهُ». بَلْ إِنَّ إِضْجاعَ الحَيَوانِ لِلذَّبْحِ قَبْلَ إِحْدادِ السِّكّينِ قَسْوَةٌ لا تَجوزُ، فَقَدْ أَضْجَعَ رَجُلٌ شاةً لِلذَّبْحِ وَهُوَ يُحِدُّ شَفْرَتَهُ، فَقالَ لَهُ ﷺ: «أَتُريدُ أَنْ تُميتَها مَوْتاتٍ؟ هَلّا أَحْدَدْتَ شَفْرَتَكَ قَبْلَ أَنْ تُضْجِعَها».", "Among the things due to an animal that is eaten are mercy to it, sharpening the knife, giving it water, and leaving it to cool after slaughter before skinning. The Messenger of God ﷺ said: “God has prescribed excellence in everything. When you kill, kill well; when you slaughter, slaughter well; let one of you sharpen his knife and give ease to the animal he slaughters.” Indeed, laying the animal down for slaughter before sharpening the knife is a cruelty that is not permissible: a man laid a sheep down to slaughter it while sharpening his knife; the Prophet ﷺ said to him: “Do you want to kill it several times? Why did you not sharpen your knife before laying it down?”", "m64-8"],
   ["وَعَنْ عَبْدِ الرَّحْمنِ بْنِ عَبْدِ اللهِ عَنْ أَبيهِ قالَ: كُنّا مَعَ رَسولِ اللهِ ﷺ في سَفَرٍ، فَانْطَلَقَ لِحاجَتِهِ، فَرَأَيْنا حُمَّرَةً مَعَها فَرْخانِ، فَأَخَذْنا فَرْخَيْها، فَجاءَتِ الحُمَّرَةُ فَجَعَلَتْ تَفْرُشُ، فَجاءَ النَّبِيُّ ﷺ فَقالَ: «مَنْ فَجَعَ هذِهِ بِوَلَدِها؟ رُدّوا وَلَدَها إِلَيْها». وَرَأى قَرْيَةَ نَمْلٍ قَدْ حَرَّقْناها، فَقالَ: «مَنْ حَرَّقَ هذِهِ؟» قُلْنا: نَحْنُ. قالَ: «إِنَّهُ لا يَنْبَغي أَنْ يُعَذِّبَ بِالنّارِ إِلّا رَبُّ النّارِ».", "ʿAbd al-Raḥmān ibn ʿAbdullāh tells from his father: We were with the Messenger of God ﷺ on a journey; he went away to relieve himself. We saw a sparrow-like bird with two young and took her young. The bird came and began to beat its wings. The Prophet ﷺ came and said: “Who has distressed this one with her young? Give her young back to her!” Seeing an ant-hill we had burned, he said, “Who burned this?” “We did,” we said. He said: “It is not fitting that anyone but the Lord of the fire punish with fire.”", "m64-9"]],
  [["وَأَمّا المُؤَسَّساتُ الاجْتِماعِيَّةُ، فَقَدْ كانَ لِلْحَيَوانِ مِنْها نَصيبٌ كَبيرٌ، وَحَسْبُنا أَنْ نَجِدَ في ثَبْتِ الأَوْقافِ القَديمَةِ أَوْقافًا خاصَّةً لِعِلاجِ الحَيَواناتِ المَريضَةِ، وَأَوْقافًا لِرَعْيِ الحَيَواناتِ العاجِزَةِ. وَلَعَلَّ أَصْدَقَ مِثالٍ عَلى الرِّفْقِ بِالحَيَوانِ في ظِلِّ حَضارَتِنا، أَنْ نَرى صَحابِيًّا جَليلًا كَأَبي الدَّرْداءِ يَكونُ لَهُ بَعيرٌ فَيَقولُ لَهُ عِنْدَ المَوْتِ: «يا أَيُّها البَعيرُ، لا تُخاصِمْني إِلى رَبِّكَ؛ فَإِنّي لَمْ أَكُنْ أُحَمِّلُكَ فَوْقَ طاقَتِكَ»، وَأَنَّ صَحابِيًّا كَعَدِيِّ بْنِ حاتِمٍ كانَ يُقَدِّمُ الخُبْزَ لِلنَّمْلِ، وَيَقولُ: «إِنَّهُنَّ جاراتٌ لَنا، وَلَهُنَّ عَلَيْنا حَقٌّ»، وَأَنَّ إِمامًا كَبيرًا كَأَبي إِسْحاقَ الشّيرازِيِّ كانَ يَمْشي في طَريقٍ مَعَهُ بَعْضُ أَصْحابِهِ، فَمَرَّ بِهِ كَلْبٌ فَزَجَرَهُ أَحَدُ أَصْحابِهِ، فَنَهاهُ الشَّيْخُ وَقالَ لَهُ: «أَما عَلِمْتَ أَنَّ الطَّريقَ مُشْتَرَكٌ بَيْنَنا وَبَيْنَهُ».", "The animal also had a great share in social institutions: it is enough to find in old endowment records special endowments set aside for treating sick animals and caring for helpless animals. Perhaps the truest example of kindness to animals in our civilization is this: a great Companion like Abū al-Dardāʾ had a camel; as he was dying he would say to it, “O camel, do not claim against me before your Lord; I did not load you beyond your strength.” A Companion like ʿAdī ibn Ḥātim would give bread to the ants and say, “They are our neighbours, and they have a right over us.” A great imam like Abū Isḥāq al-Shīrāzī, walking on the road with some friends, saw a dog pass; one of his friends chased it; the shaykh stopped him from this and said: “Do you not know that the road is shared between us and it?”", "m64-10"]]] },
 { t: "dy", ar: "أَوَّلًا: الاسْتيعابُ — تَدْريبٌ (١): ضَعْ عَلامَةَ (✓) أَوْ (✗)، ثُمَّ صَحِّحِ الخَطَأَ", ogeler: [
  ["الحَيَوانُ لَهُ خَصائِصُ وَطَبائِعُ وَشُعورٌ.", true, "", "The animal has characteristics, nature and feelings."],
  ["مُعامَلَةُ الإِنْسانِ لِلْحَيَوانِ قَدْ تُدْخِلُهُ الجَنَّةَ أَوِ النّارَ.", true, "", "A person's treatment of an animal can admit him to Paradise or Hell."],
  ["نَزَلَ الرَّجُلُ البِئْرَ وَمَلَأَ الكوبَ وَسَقى الكَلْبَ.", false, "نَزَلَ الرَّجُلُ البِئْرَ وَمَلَأَ خُفَّهُ وَسَقى الكَلْبَ.", "The man went down into the well, filled the cup and gave the dog water."],
  ["دَخَلَتِ المَرْأَةُ النّارَ بِسَبَبِ الكَلْبِ الَّذي لَمْ تُطْعِمْهُ.", false, "دَخَلَتِ المَرْأَةُ النّارَ بِسَبَبِ هِرَّةٍ رَبَطَتْها فَلَمْ تُطْعِمْها.", "The woman entered Hell because of a dog she did not feed."],
  ["شَكا الجَمَلُ إِلى الرَّسولِ ﷺ أَنَّ صاحِبَهُ يَضْرِبُهُ.", false, "شَكا الجَمَلُ أَنَّ صاحِبَهُ يُجيعُهُ وَيُدْئِبُهُ (يُتْعِبُهُ).", "The camel complained to the Prophet ﷺ that its owner beat it."],
  ["لا يَجوزُ أَنْ يُعَذَّبَ الحَيَوانُ، أَوْ يُكْوى بِالنّارِ.", true, "", "Torturing an animal or branding it with fire is not permissible."],
  ["في الإِسْلامِ تُقْتَلُ الحَيَواناتُ المَريضَةُ وَالعاجِزَةُ.", false, "في الإِسْلامِ أَوْقافٌ لِعِلاجِ الحَيَواناتِ المَريضَةِ وَرَعْيِ العاجِزَةِ.", "In Islam sick and helpless animals are killed."],
  ["إِضْجاعُ الحَيَوانِ لِلذَّبْحِ بَعْدَ إِحْدادِ السِّكّينِ قَسْوَةٌ لا تَجوزُ.", false, "إِضْجاعُ الحَيَوانِ لِلذَّبْحِ قَبْلَ إِحْدادِ السِّكّينِ قَسْوَةٌ لا تَجوزُ.", "Laying the animal down after sharpening the knife is a cruelty that is not permissible."]] },
 { t: "acik", ar: "تَدْريبٌ (٢): اذْكُرِ المُناسَبَةَ الَّتي قيلَ فيها كُلُّ حَديثٍ مِمّا يَلي", aciklama: "First recall it yourself; then look at the answer.", ogeler: [
  ["«في كُلِّ ذاتِ كَبِدٍ رَطْبَةٍ أَجْرٌ».", "جَوابًا لِلصَّحابَةِ لَمّا سَأَلوا عَنِ الأَجْرِ في البَهائِمِ، بَعْدَ قِصَّةِ الرَّجُلِ الَّذي سَقى الكَلْبَ.", "In every living being with a moist liver there is reward."],
  ["«أَلا تَتَّقي اللهَ في هذِهِ البَهيمَةِ».", "قالَهُ لِصاحِبِ الجَمَلِ الَّذي شَكا إِلَيْهِ أَنَّهُ يُجيعُهُ وَيُتْعِبُهُ.", "Do you not fear God concerning this animal?"],
  ["«لَعَنَ اللهُ الَّذي وَسَمَهُ» (أَيِ الحِمارَ).", "حينَ مَرَّ عَلَيْهِ حِمارٌ قَدْ وُسِمَ في وَجْهِهِ.", "May God curse the one who branded it."],
  ["«أَتُريدُ أَنْ تُميتَها مَوْتاتٍ».", "قالَهُ لِرَجُلٍ أَضْجَعَ شاةً لِلذَّبْحِ وَهُوَ يُحِدُّ شَفْرَتَهُ.", "Do you want to kill it several times?"],
  ["«لا يَنْبَغي أَنْ يُعَذِّبَ بِالنّارِ إِلّا رَبُّ النّارِ».", "لَمّا رَأى قَرْيَةَ نَمْلٍ قَدْ أَحْرَقَها الصَّحابَةُ.", "With fire only the Lord of the fire punishes."],
  ["«بَيْنَما رَجُلٌ يَمْشي بِطَريقٍ إِذِ اشْتَدَّ بِهِ العَطَشُ…»", "في بَيانِ أَنَّ الرَّحْمَةَ بِالحَيَوانِ قَدْ تُدْخِلُ صاحِبَها الجَنَّةَ.", "A man was walking on the road when his thirst became severe…"],
  ["«مَنْ رَبُّ هذا الجَمَلِ؟…»", "لَمّا دَخَلَ حائِطَ رَجُلٍ مِنَ الأَنْصارِ، فَرَأى جَمَلًا يَحِنُّ وَتَذْرِفُ عَيْناهُ.", "Who is the owner of this camel?"],
  ["«مَنْ فَجَعَ هذِهِ بِوَلَدِها؟»", "لَمّا أَخَذَ الصَّحابَةُ فَرْخَيِ الحُمَّرَةِ، فَجَعَلَتْ تَفْرُشُ.", "Who distressed this one with her young?"],
  ["«لَعَنَ رَسولُ اللهِ مَنِ اتَّخَذَ شَيْئًا فيهِ الرّوحُ غَرَضًا».", "قالَهُ ابْنُ عُمَرَ لِفِتْيانٍ مِنْ قُرَيْشٍ نَصَبوا طَيْرًا يَرْمونَهُ.", "The Messenger cursed whoever takes a living thing as a target."]] }
]},
// ---------------- DERS 65 ----------------
{ no: 65, kisa: "اسْتيعابٌ وَمُفْرَداتٌ", ar: "اسْتيعابٌ وَمُفْرَداتٌ وَتَعْبيراتٌ", tr: "Comprehension, words and expressions", ozet: "Paragraph ideas, short answers, singulars, antonyms, expressions, set phrases.", bloklar: [
 { t: "esle", ar: "تَدْريبٌ (٣): وائِمْ بَيْنَ الفِكْرَةِ في (أ) وَرَقْمِ الفِقْرَةِ الَّتي وَرَدَتْ فيها في (ب)", ciftler: [
  ["مُعامَلَةُ الإِنْسانِ لِلْحَيَوانِ، قَدْ تُدْخِلُهُ الجَنَّةَ أَوِ النّارَ.", "الفِقْرَةُ (١)", "A person's treatment of an animal may admit to Paradise or Hell."],
  ["سَخَّرَ اللهُ بَعْضَ الحَيَواناتِ لِلْإِنْسانِ.", "الفِقْرَةُ (٢)", "God placed some animals at man's service."],
  ["لا يَجوزُ إِرْهاقُ الحَيَوانِ أَوْ قَتْلُهُ.", "الفِقْرَةُ (٣)", "Tiring or killing an animal is not permissible."],
  ["الرَّحْمَةُ واجِبَةٌ حَتّى عِنْدَ ذَبْحِ الحَيَوانِ.", "الفِقْرَةُ (٤)", "Mercy is necessary even in slaughter."],
  ["الصَّحابَةُ كانوا يُطَبِّقونَ مَبْدَأَ الرِّفْقِ بِالحَيَوانِ.", "الفِقْرَةُ (٥)", "The Companions applied the principle of kindness to animals."]],
  not: "Idea 1 in the book (the ban on sitting on an animal's back and overloading it) is also in paragraph 2." },
 { t: "acik", ar: "تَدْريبٌ (٤): أَجِبْ بِاخْتِصارٍ عَمّا يَلي", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["كَيْفَ سَقى الرَّجُلُ الكَلْبَ؟", "نَزَلَ البِئْرَ فَمَلَأَ خُفَّهُ ماءً، ثُمَّ أَمْسَكَهُ بِفيهِ فَسَقاهُ.", "How did the man give the dog water?"],
  ["اذْكُرْ دَليلًا مِنَ القُرْآنِ عَلى أَنَّ جَميعَ أَنْواعِ الحَيَواناتِ أُمَمٌ مِثْلُ البَشَرِ.", "﴿وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ﴾.", "Bring a proof from the Qur'an that animals are communities like humans."],
  ["كَمْ مَرَّةً نَزَلَ الرَّجُلُ إِلى البِئْرِ؟", "مَرَّتَيْنِ.", "How many times did the man go down into the well?"],
  ["لِماذا نَزَلَ في المَرَّةِ الأولى؟", "لِيَشْرَبَ؛ لِأَنَّهُ اشْتَدَّ عَلَيْهِ العَطَشُ.", "Why did he go down the first time?"],
  ["ماذا فَعَلَ الجَمَلُ عِنْدَما رَأى الرَّسولَ ﷺ؟", "حَنَّ وَذَرَفَتْ عَيْناهُ.", "What did the camel do when it saw the Prophet ﷺ?"],
  ["ماذا فَهِمَ الرَّسولُ ﷺ مِنَ الجَمَلِ؟", "أَنَّ صاحِبَهُ يُجيعُهُ وَيُتْعِبُهُ بِكَثْرَةِ العَمَلِ.", "What did the Prophet ﷺ understand from the camel?"],
  ["ماذا يُفْعَلُ بِالحَيَوانِ قَبْلَ الذَّبْحِ وَبَعْدَهُ؟", "قَبْلَهُ: تُحَدُّ السِّكّينُ وَيُسْقى الماءَ وَلا يُضْجَعُ قَبْلَ إِحْدادِ السِّكّينِ؛ وَبَعْدَهُ: يُراحُ قَبْلَ السَّلْخِ.", "What is done to the animal before and after slaughter?"],
  ["عَلى أَيِّ شَيْءٍ يَدُلُّ كَلامُ أَبي الدَّرْداءِ مَعَ بَعيرِهِ؟", "عَلى رِفْقِهِ بِالحَيَوانِ، وَخَوْفِهِ مِنْ مُحاسَبَةِ اللهِ لَهُ.", "What does Abū al-Dardāʾ's speaking to his camel show?"],
  ["ماذا كانَ يُقَدِّمُ عَدِيُّ بْنُ حاتِمٍ الطّائِيُّ لِلنَّمْلِ؟", "الخُبْزَ.", "What would ʿAdī ibn Ḥātim give to the ants?"]] },
 { t: "bosluk", ar: "ثانِيًا: المُفْرَداتُ — تَدْريبٌ (١): الجُموعُ الَّتي تَحْتَها خَطٌّ وَرَدَتْ في النَّصِّ، هاتِ مُفْرَدَ كُلٍّ مِنْها، وَضَعْهُ في الفَراغِ", kutu: ["البَهيمَةُ", "مِثْلَ", "دابَّةٍ", "وَجْهٍ", "المُؤَسَّسَةُ", "صاحِبُ", "طَبيعَتُهُ"], ogeler: [
  ["لا تُشابِهُ هذِهِ ___ تِلْكَ [[البَهائِمَ]] القَريبَةَ مِنْها.", "البَهيمَةُ", null, "This animal is not like those animals near it."],
  ["هذا الطّائِرُ لَيْسَ ___ هذا الطّائِرِ، وَالطَّيْرُ وَالحَيَوانُ أُمَمٌ [[أَمْثالُكُمْ]].", "مِثْلَ", null, "This bird is not like that bird; birds and animals are communities like you."],
  ["خَلَقَ اللهُ كُلَّ هذِهِ [[الدَّوابِّ]]، وَكُلُّ ___ يَرْزُقُها اللهُ.", "دابَّةٍ", null, "God created all these creatures; God provides for every creature."],
  ["بِأَيِّ ___ مِنَ [[الوُجوهِ]] تُقابِلُ اللهَ يَوْمَ القِيامَةِ!", "وَجْهٍ", null, "With what face will you come before God on the Day of Resurrection!"],
  ["هذِهِ ___ ناجِحَةٌ، أَمّا [[المُؤَسَّساتُ]] الأُخْرى فَلَيْسَتْ ناجِحَةً.", "المُؤَسَّسَةُ", null, "This institution is successful, the other institutions are not."],
  ["___ هذا المَصْنَعِ أَفْضَلُ مِنْ [[أَصْحابِ]] المَصانِعِ الأُخْرى.", "صاحِبُ", null, "The owner of this factory is better than the owners of the other factories."],
  ["لِلْإِنْسانِ ___ وَلِلْحَيَواناتِ [[طَبائِعُها]] وَخَصائِصُها.", "طَبيعَتُهُ", null, "Man has his own nature, and animals have their own natures and characteristics."]] },
 { t: "bosluk", ar: "تَدْريبٌ (٢): هاتِ مِنَ النَّصِّ الكَلِماتِ المُضادَّةَ في المَعْنى لِما تَحْتَهُ خَطٌّ، وَاكْتُبْها في الفَراغِ", kutu: ["الإِحْسانِ", "الرِّفْقِ", "خَرَجَ", "يَنْهى", "يُعَذِّبُ", "رَطْبَةً", "يَبيعُ", "ضَعْفٍ"], ogeler: [
  ["أَمَرَ اللهُ بِـ___ وَنَهى عَنِ [[الإِساءَةِ]].", "الإِحْسانِ", null, "God commanded good and forbade evil."],
  ["نُهينا عَنِ [[القَسْوَةِ]] عَلى الحَيَوانِ، وَأُمِرْنا بِـ___ بِهِ.", "الرِّفْقِ", null, "We were forbidden harshness to animals and commanded kindness to them."],
  ["[[نَزَلَ]] الرَّجُلُ البِئْرَ، ثُمَّ ___ وَسَقى الكَلْبَ.", "خَرَجَ", null, "The man went down into the well, then came out and gave the dog water."],
  ["الكافِرُ [[يَأْمُرُ]] بِالمُنْكَرِ، وَ___ عَنِ المَعْروفِ.", "يَنْهى", null, "The disbeliever commands evil and prevents good."],
  ["اللهُ [[يَرْحَمُ]] المُؤْمِنينَ، وَ___ الكافِرينَ.", "يُعَذِّبُ", null, "God has mercy on the believers and punishes the disbelievers."],
  ["أَطْعِمِ الحَيَواناتِ أَعْشابًا ___، فَذلِكَ أَحْسَنُ لَها مِنَ [[اليابِسَةِ]].", "رَطْبَةً", null, "Feed animals fresh grass; this is better for them than dry grass."],
  ["المُسْلِمُ لا [[يَشْتَري]] إِلّا الحَلالَ، وَلا ___ إِلّا الحَلالَ أَيْضًا.", "يَبيعُ", null, "The Muslim takes only the lawful and sells only the lawful.", "‘يَبيعُ’ does not occur in the text."],
  ["اللهُ جَعَلَ مِنْ بَعْدِ ___ [[قُوَّةً]].", "ضَعْفٍ", null, "God gave strength after weakness.", "‘ضَعْف’ does not occur in the text; it points to verse 54 of al-Rūm."]] },
 { t: "acik", ar: "تَدْريبٌ (٣): اسْتَخْدِمْ كُلَّ تَعْبيرٍ مِنَ التَّعْبيراتِ التّالِيَةِ في جُمْلَةٍ مِنْ إِنْشائِكَ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["غَفَرَ لِـ", "غَفَرَ اللهُ لِلرَّجُلِ الَّذي سَقى الكَلْبَ.", "he forgave"], ["شَكَرَ لِـ", "شَكَرْتُ لِصَديقي مُساعَدَتَهُ.", "he thanked"], ["يَأْكُلُ مِنْ", "يَأْكُلُ الطِّفْلُ مِنْ طَعامِ أُمِّهِ.", "he eats from"],
  ["يَلْعَبُ بِـ", "لا يَلْعَبُ المُسْلِمُ بِالحَيَوانِ.", "he plays with"], ["أَلْزَمَ بِـ", "أَلْزَمَ القاضي المُعْتَدِيَ بِدَفْعِ الثَّمَنِ.", "he made obligatory on"], ["يوقِفُ في", "يوقِفُ السّائِقُ سَيّارَتَهُ في المَوْقِفِ.", "he stops at"],
  ["يَنْهى عَنْ", "يَنْهى الإِسْلامُ عَنِ القَسْوَةِ عَلى الحَيَوانِ.", "he forbids"], ["شَكا إِلى", "شَكا المَريضُ إِلى الطَّبيبِ أَلَمَهُ.", "he complained to"], ["مَرَّ عَلى", "مَرَرْتُ عَلى صَديقي في طَريقي.", "he passed by"],
  ["لا يَنْبَغي أَنْ", "لا يَنْبَغي أَنْ نُحَمِّلَ الحَيَوانَ فَوْقَ طاقَتِهِ.", "must not"]] },
 { t: "acik", ar: "تَدْريبٌ (٤): اقْرَأِ الجُمَلَ التّالِيَةَ، ثُمَّ انْسُجْ عَلى مِنْوالِها: ساقَ سَوْقًا شَديدًا.", aciklama: "First write it yourself; then look at the sample sentence.", ogeler: [
  ["تَضْرِبُ … قَوِيًّا.", "تَضْرِبُ ضَرْبًا قَوِيًّا.", "He strikes hard."], ["يَفْعَلُ … جَيِّدًا.", "يَفْعَلُ فِعْلًا جَيِّدًا.", "He does a good deed."], ["صامَ … صَحيحًا.", "صامَ صَوْمًا صَحيحًا.", "He kept a valid fast."], ["نَجَحَ …", "نَجَحَ نَجاحًا باهِرًا.", "He achieved a brilliant success."],
  ["… تَأْثيرًا …", "أَثَّرَ تَأْثيرًا كَبيرًا.", "He made a great impression."], ["… مُحاوَلَةً …", "حاوَلَ مُحاوَلَةً جادَّةً.", "He made a serious attempt."], ["دَعا … مُسْتَجابَةً.", "دَعا دَعْوَةً مُسْتَجابَةً.", "He made an accepted supplication."],
  ["رَغِبَ … صادِقَةً.", "رَغِبَ رَغْبَةً صادِقَةً.", "He asked sincerely."], ["… نَوْمًا عَميقًا.", "نامَ نَوْمًا عَميقًا.", "He slept a deep sleep."], ["… فَسادًا …", "فَسَدَ فَسادًا كَبيرًا.", "He was very upset."]] }
]},
// ---------------- DERS 66 ----------------
{ no: 66, kisa: "التَّمْييزُ", ar: "قَواعِدُ اللُّغَةِ (أ): التَّمْييزُ", tr: "Grammar: specification (tamyīz)", ozet: "The accusative indefinite noun that removes the vagueness of a thing (single) or of a relation (sentence): specification of the thing and specification of the relation.", bloklar: [
 { t: "ornek", ar: "الأَمْثِلَةُ: ادْرُسْ وَتَأَمَّلْ", ogeler: [
  ["(أ) أَعْطَيْتُهُ زَكاةَ الفِطْرِ صاعًا [[بُرًّا]].", "I gave him a ṣāʿ of wheat as zakat al-fiṭr."], ["(أ) اشْتَرى المُزارِعُ فَدّانًا [[أَرْضًا]].", "The farmer bought a feddan of land."], ["(أ) ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ [[خَيْرًا]] يَرَهُ﴾", "Whoever does an atom's weight of good will see it."],
  ["(أ) ﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ [[كَوْكَبًا]]﴾", "I saw eleven stars."], ["(أ) ﴿فَاجْلِدُوهُمْ ثَمَانِينَ [[جَلْدَةً]]﴾", "Strike them eighty lashes."],
  ["(ب) ﴿كَفَىٰ بِاللَّهِ [[شَهِيدًا]] بَيْنِي وَبَيْنَكُمْ﴾", "God suffices as a witness between me and you."], ["(ب) ﴿أَنَا أَكْثَرُ مِنْكَ [[مَالًا]] وَأَعَزُّ [[نَفَرًا]]﴾", "I am greater than you in wealth and mightier in manpower."],
  ["(ب) ﴿فَكُلِي وَاشْرَبِي وَقَرِّي [[عَيْنًا]]﴾", "Eat, drink and be of cheerful eye."], ["(ب) ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ [[حَدِيثًا]]﴾", "Who is truer than God in speech?"], ["(ب) ﴿كَبُرَتْ [[كَلِمَةً]] تَخْرُجُ مِنْ أَفْوَاهِهِمْ﴾", "How grave it was as a word coming out of their mouths!"]] },
 { t: "kural", ar: "الشَّرْحُ", metin: "تَأَمَّلْ ما تَحْتَهُ خَطٌّ في الأَمْثِلَةِ السّابِقَةِ، تَجِدْ أَنَّها أَسْماءٌ مَنْصوبَةٌ، وَتَجِدُها بَيَّنَتْ شَيْئًا قَبْلَها غَيْرَ واضِحٍ، فَوَضَّحَتْهُ وَمَيَّزَتْهُ؛ وَلِذا تُسَمّى تَمْييزًا. وَفي القائِمَةِ (أ) تَجِدُ أَنَّ التَّمْييزَ فيها رَفَعَ إِبْهامَ مُفْرَدٍ قَبْلَهُ: كَيْلًا، أَوْ وَزْنًا، أَوْ مِساحَةً، أَوْ عَدَدًا، وَهُوَ عَلى تَقْديرِ (مِنْ)؛ فَكَأَنَّهُ قالَ: صاعًا مِنْ بُرٍّ، وَفَدّانًا مِنْ أَرْضٍ، وَمِثْقالَ ذَرَّةٍ مِنْ خَيْرٍ، وَأَحَدَ عَشَرَ مِنَ الكَواكِبِ، وَيُسَمّى تَمْييزَ الذّاتِ، أَوْ تَمْييزَ المُفْرَدِ، أَوِ التَّمْييزَ المَلْفوظَ. وَفي القائِمَةِ (ب) تَجِدُ أَنَّ المُبْهَمَ لَيْسَ مُفْرَدًا، وَإِنَّما هُوَ جُمْلَةٌ؛ فَنِسْبَةُ الكِفايَةِ: مِنْ أَيِّ ناحِيَةٍ؟ إِنَّها مِنْ ناحِيَةِ الشَّهادَةِ، وَنِسْبَةُ الكَثْرَةِ لِلْمُتَكَلِّمِ: مِنْ أَيِّ ناحِيَةٍ؟ إِنَّها مِنْ ناحِيَةِ المالِ… وَيُسَمّى تَمْييزَ النِّسْبَةِ، أَوِ التَّمْييزَ المَلْحوظَ، أَوْ تَمْييزَ الجُمْلَةِ.", tr: "The underlined words are accusative nouns that explain a vague thing before them: specification. In (أ) the specification removes the vagueness of a single word before it that indicates a measure, weight, area or number; it is in the sense of مِنْ (صاعًا مِنْ بُرٍّ): specification of the thing (single, uttered). In (ب) what is vague is a sentence: in what respect is the sufficiency? in the respect of witness; in what respect is the abundance? in the respect of wealth: specification of the relation (implied, sentence specification)." },
 { t: "kural", ar: "القاعِدَةُ", metin: "التَّمْييزُ: اسْمٌ نَكِرَةٌ مَنْصوبٌ، يُذْكَرُ لِبَيانِ مُبْهَمٍ مِنْ ذاتٍ (مُفْرَدٍ) أَوْ نِسْبَةٍ (جُمْلَةٍ)، وَيُسَمّى تَمْييزَ الذّاتِ مَلْفوظًا، وَتَمْييزَ النِّسْبَةِ مَلْحوظًا. وَالمَلْفوظُ هُوَ تَمْييزُ الكَيْلِ وَالوَزْنِ وَالمِساحَةِ وَالعَدَدِ. وَلا يَكونُ التَّمْييزُ جُمْلَةً وَلا شِبْهَ جُمْلَةٍ، بَلِ اسْمًا صَريحًا.", tr: "The specification is an accusative indefinite noun said to explain the vagueness of a thing (single) or of a relation (sentence). Specification of the thing (uttered) is specification of a measure, weight, area and number; specification of the relation is implied. The specification is not a sentence or quasi-sentence, but an explicit noun." },
 { t: "siniflandir", ar: "تَدْريبٌ (١): ضَعْ خَطًّا تَحْتَ تَمْييزِ الذّاتِ، وَخَطَّيْنِ تَحْتَ تَمْييزِ النِّسْبَةِ", soru: "The kind of specification?", gruplar: ["تَمْييزُ ذاتٍ", "تَمْييزُ نِسْبَةٍ"], ogeler: [
  ["﴿وَلَوْ جِئْنَا بِمِثْلِهِ [[مَدَدًا]]﴾", 0], ["﴿إِنَّ هَٰذَا أَخِي لَهُ تِسْعٌ وَتِسْعُونَ [[نَعْجَةً]]﴾", 0], ["﴿وَاشْتَعَلَ الرَّأْسُ [[شَيْبًا]]﴾", 1], ["﴿فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ [[عَامًا]]﴾", 0],
  ["﴿وَفَجَّرْنَا الْأَرْضَ [[عُيُونًا]]﴾", 1], ["﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ [[قِيلًا]]﴾", 1], ["﴿فَلَنْ يُقْبَلَ مِنْ أَحَدِهِمْ مِلْءُ الْأَرْضِ [[ذَهَبًا]]﴾", 0], ["﴿وَوَاعَدْنَا مُوسَىٰ ثَلَاثِينَ [[لَيْلَةً]]﴾", 0],
  ["﴿لَتَجِدَنَّ أَشَدَّ النَّاسِ [[عَدَاوَةً]] لِلَّذِينَ آمَنُوا الْيَهُودَ وَالَّذِينَ أَشْرَكُوا﴾", 1], ["﴿إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ [[مَالًا]] وَوَلَدًا﴾", 1], ["﴿إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ [[مَرَّةً]] فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾", 0]],
  not: "مَدَدًا and ذَهَبًا: specification of the thing, because they come after words indicating measure such as مِثْل and مِلْء. عُيونًا: specification of the relation (originally ‘We caused the springs of the earth to gush forth’, transformed from the object)." },
 { t: "acik", ar: "تَدْريبٌ (٢): اسْتَخْرِجِ التَّمْييزَ فيما يَلي، وَبَيِّنْ نَوْعَهُ", aciklama: "Find it yourself first; then look at the answer.", ogeler: [
  ["﴿أُولَٰئِكَ شَرٌّ مَكَانًا وَأَضَلُّ عَنْ سَوَاءِ السَّبِيلِ﴾", "مَكانًا — تَمْييزُ نِسْبَةٍ", "They are worse in position and more astray from the right path."], ["﴿حَتَّىٰ إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً﴾", "سَنَةً — تَمْييزُ ذاتٍ (عَدَدٌ)", "When he reached maturity and reached forty years…"],
  ["﴿ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾", "تَأْويلًا — تَمْييزُ نِسْبَةٍ", "This is better and fairer in outcome."], ["﴿فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا﴾", "ناصِرًا، عَدَدًا — تَمْييزُ نِسْبَةٍ", "They will know whose helper is weaker and whose numbers fewer."],
  ["﴿فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَكَانًا وَأَضْعَفُ جُنْدًا﴾", "مَكانًا، جُنْدًا — تَمْييزُ نِسْبَةٍ", "They will know who is worse in position and weaker in soldiers."], ["﴿فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا﴾", "عامًا — تَمْييزُ ذاتٍ (عَدَدٌ)", "Fifty years less than a thousand years remained among them."],
  ["﴿قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً﴾", "شَهادَةً — تَمْييزُ نِسْبَةٍ", "Say: What thing is greatest in testimony?"], ["﴿كَانُوا أَشَدَّ مِنْكُمْ قُوَّةً وَأَكْثَرَ أَمْوَالًا وَأَوْلَادًا﴾", "قُوَّةً، أَمْوالًا، أَوْلادًا — تَمْييزُ نِسْبَةٍ", "They were stronger than you in power, and more in wealth and children."],
  ["﴿لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا﴾", "نَفْعًا — تَمْييزُ نِسْبَةٍ", "You do not know which of them is nearer to you in benefit."]] },
 { t: "acik", ar: "تَدْريبٌ (٣): امْلَأِ الفَراغَ في الجُمَلِ التّالِيَةِ بِتَمْييزٍ مُناسِبٍ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["الدّاعِيَةُ العالِمُ أَكْثَرُ … مِنَ الدّاعِيَةِ الجاهِلِ.", "نَفْعًا", "A scholar-preacher is more beneficial than an ignorant preacher."], ["الرَّجُلُ الشُّجاعُ أَقْوى … مِنَ الجَبانِ.", "قَلْبًا", "The brave man is stronger in heart than the coward."],
  ["نَصَحَني الطَّبيبُ أَنْ أَشْرَبَ لِتْرًا …", "حَليبًا", "The doctor advised me to drink a litre of milk."], ["زَرَعْتُ أَرْضي …", "قَمْحًا", "I sowed my land with wheat.", "Here the specification is transformed from the object (زَرَعْتُ قَمْحَ أَرْضي)."],
  ["ما أَعْظَمَ الشَّيْخَ …", "عِلْمًا", "How great the teacher is in knowledge!"], ["لِلّهِ دَرُّكَ …", "فارِسًا", "What a gallant horseman you are!"],
  ["حَسْبُكَ بِسالِمٍ …", "صَديقًا", "Sālim suffices you as a friend."], ["احْفَظْ خَمْسَ … أُسْبوعِيًّا.", "صَفَحاتٍ", "Memorize five pages a week.", "The specification of numbers 3-10 is a genitive plural (صَفَحاتٍ); it is not accusative."],
  ["اشْتَرَيْتُ مِتْرًا …", "قُماشًا", "I bought a metre of cloth."], ["باعَ البَقّالُ رِطْلًا …", "عَسَلًا", "The grocer sold a ratl of honey."],
  ["ارْتَفَعَتِ الجامِعَةُ …", "مَكانَةً", "The university's prestige rose."], ["فاضَ الإِناءُ …", "ماءً", "The vessel overflowed with water."],
  ["هُوَ أَكْثَرُ مِنْ أَخيهِ …", "مالًا", "He is richer in wealth than his brother."], ["ما أَعْظَمَ الكِتابَ …", "نَفْعًا", "How great the book is in benefit!"],
  ["أَنْعِمْ بِسَلْمانَ …", "رَجُلًا", "What a fine man Salmān is!"], ["كَفى بِالمَوْتِ …", "واعِظًا", "Death suffices as an admonisher."],
  ["هذِهِ السَّيّارَةُ أَفْضَلُ مِنْ تِلْكَ …", "صِناعَةً", "This car is better than that in make."], ["الطّائِرَةُ أَحْسَنُ مِنَ السَّيّارَةِ …", "سُرْعَةً", "The plane is better than the car in speed."],
  ["جامِعَتُنا أَكْبَرُ مِنْ جامِعَتِكُمْ …", "مِساحَةً", "Our university is bigger than yours in area."], ["المَسافَةُ بَيْنَ مَكَّةَ وَالمَدينَةِ ٤٠٠ …", "كيلومِتْرٍ", "Between Mecca and Medina is 400 kilometres.", "The specification of a hundred and a thousand is a genitive singular (كيلومِتْرٍ)."]] },
 { t: "acik", ar: "تَدْريبٌ (٤): امْلَأِ الفَراغَ في الجُمَلِ التّالِيَةِ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["سُلَيْمانُ … مِنْ أَخيهِ حَمْزَةَ صَدْرًا.", "أَوْسَعُ", "Sulaymān is broader of chest than his brother Ḥamza."], ["دَفَعْتُ لَهُ … شَعيرًا.", "صاعًا", "I gave him a ṣāʿ of barley."],
  ["ذَهَبْتُ إِلى السّوقِ، وَاشْتَرَيْتُ … صوفًا.", "رِطْلًا", "I went to the market and bought a ratl of wool."], ["طابَتْ … هَواءً.", "المَدينَةُ", "The weather of the city became fine."],
  ["الأُسْرَةُ في الدُّوَلِ النّامِيَةِ … تَرابُطًا مِنْها في الدُّوَلِ المُتَقَدِّمَةِ.", "أَكْثَرُ", "In developing countries the family is more attached than in developed countries."], ["اخْتَبَرْتُ شُعْبَتَيْنِ مِنْ شُعَبِ العَرَبِيَّةِ فَوَجَدْتُ شُعْبَةَ (أ) … تَقَدُّمًا مِنْ شُعْبَةِ (ب).", "أَكْثَرَ", "I tested two branches of Arabic; I found branch (A) more advanced than (B)."]] },
 { t: "acik", ar: "تَدْريبٌ (٥): هاتِ أَرْبَعَةَ أَمْثِلَةٍ لِتَمْييزِ الذّاتِ، وَأَرْبَعَةَ أَمْثِلَةٍ لِتَمْييزِ النِّسْبَةِ في جُمَلٍ مُفيدَةٍ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["تَمْييزُ الذّاتِ", "اشْتَرَيْتُ كيلو تَمْرًا. — شَرِبْتُ كوبًا حَليبًا. — في الفَصْلِ عِشْرونَ طالِبًا. — زَرَعْتُ فَدّانًا قُطْنًا.", "specification of the thing"],
  ["تَمْييزُ النِّسْبَةِ", "طابَ الطِّفْلُ نَفْسًا. — المُؤْمِنُ أَحْسَنُ خُلُقًا. — امْتَلَأَ القَلْبُ سُرورًا. — زادَ العالِمُ تَواضُعًا.", "specification of the relation"]] }
]},
// ---------------- DERS 67 ----------------
{ no: 67, kisa: "فَهْمُ المَسْموعِ", ar: "فَهْمُ المَسْموعِ", tr: "Listening", ozet: "The world of animals: kinds of animals, their movement and their protection — a listening text in two parts.", bloklar: [
 { t: "dinle", s: "l67a", ar: "القِسْمُ الأَوَّلُ: أَنْواعُ الحَيَواناتِ", aciklama: "Animals in the Qur'an, animals' benefits to man, kinds by their movement, size and habitat. Listen first, then answer the questions.", metin: [
  ["يَتَحَدَّثُ القُرْآنُ الكَريمُ في كَثيرٍ مِنْ سُوَرِهِ عَنِ الحَيَوانِ، وَيَذْكُرُ أَنْواعَهُ وَأَوْصافَهُ وَمَنافِعَهُ، وَسُمِّيَتْ بَعْضُ سُوَرِ القُرْآنِ بِأَسْماءِ الحَيَواناتِ، كَالبَقَرَةِ، وَالنَّمْلِ، وَالنَّحْلِ، وَالعَنْكَبوتِ، وَالأَنْعامِ، وَالفيلِ.", "The Noble Qur'an speaks of animals in many of its suras; it mentions their kinds, qualities and benefits. Some suras of the Qur'an are named after animals: al-Baqara, al-Naml, al-Naḥl, al-ʿAnkabūt, al-Anʿām and al-Fīl."],
  ["وَلِلْحَيَوانِ أَهَمِّيَّةٌ كَبيرَةٌ لِلْإِنْسانِ؛ فَهُوَ يَتَغَذّى بِلُحومِ الحَيَواناتِ وَشُحومِها وَأَلْبانِها وَبَيْضِها وَعَسَلِها، وَيَسْتَفيدُ مِنْ صوفِها وَجُلودِها وَحَريرِها وَفِرائِها في الكِساءِ، وَيَسْتَعْمِلُ بَعْضَها كَالخَيْلِ وَالبِغالِ وَالحَميرِ وَالجِمالِ وَالثّيرانِ في النَّقْلِ وَالزّينَةِ وَالحَرْبِ وَزِراعَةِ الأَرْضِ.", "The animal is of great importance to man: man is fed by the meat, fat, milk, eggs and honey of animals; he benefits in clothing from their wool, hides, silk and fur; he uses some of them, such as horses, mules, donkeys, camels and oxen, for carrying, for adornment, for war and for working the land."],
  ["تَخْتَلِفُ الحَيَواناتُ في حَرَكَتِها؛ فَمِنْها ما يَمْشي عَلى الأَرْضِ كَالحِصانِ، وَمِنْها ما يَزْحَفُ عَلى الأَرْضِ كَالثُّعْبانِ، وَمِنْها ما يَطيرُ في الهَواءِ كَالصَّقْرِ، وَمِنْها ما يَسْبَحُ في الماءِ كَالسَّمَكِ. وَتَخْتَلِفُ الحَيَواناتُ في الحَجْمِ؛ فَهُناكَ حَيَواناتٌ ضَخْمَةٌ كَالحوتِ وَالفيلِ، وَحَيَواناتٌ صَغيرَةٌ جِدًّا كَالنَّمْلِ وَالذُّبابِ.", "Animals differ in their movement: some walk on the ground like the horse, some crawl on the ground like the snake, some fly in the air like the falcon, some swim in water like the fish. They also differ in size: there are huge animals like the whale and the elephant, and very small animals like the ant and the fly."],
  ["وَبَعْضُ الحَيَواناتِ أَليفٌ، وَهُوَ الَّذي يَعيشُ مَعَ الإِنْسانِ كَالبَقَرَةِ وَالقِطِّ، وَأَكْثَرُها وَحْشِيٌّ كَالأَسَدِ وَالنَّمِرِ. وَمِنَ الحَيَواناتِ ما يَعيشُ في البَرِّ كَالأَفْيالِ وَالفَراشاتِ، وَمِنْها ما يَعيشُ في الماءِ كَالسَّمَكِ وَالحيتانِ، وَمِنْها ما يَعيشُ في البَرِّ وَالماءِ كَالضَّفادِعِ، وَلا يَعْرِفُ العُلَماءُ عَدَدَ الحَيَواناتِ المَوْجودَةِ عَلى الأَرْضِ.", "Some animals are domestic, living with man like the cow and the cat; most are wild like the lion and the tiger. There are those that live on land like the elephant and the butterfly, those that live in water like the fish and the whale, and those that live both on land and in water like the frog. Scholars do not know the number of animals on earth."]],
  not: "The text was transcribed from the recording; the book contains only the questions." },
 { t: "acik", ar: "تَدْريبٌ (١): مَثِّلْ لِما يَلي مِمّا اسْتَمَعْتَ إِلَيْهِ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["حَيَوانٌ يَطيرُ.", "الصَّقْرُ.", "flying animal"], ["حَيَوانٌ يَسْبَحُ.", "السَّمَكُ.", "swimming animal"], ["حَيَوانٌ يَزْحَفُ.", "الثُّعْبانُ.", "crawling animal"], ["حَيَوانٌ يَمْشي.", "الحِصانُ.", "walking animal"],
  ["حَيَوانٌ يَعيشُ في الماءِ وَفي الأَرْضِ.", "الضِّفْدَعُ.", "animal living both in water and on land"]] },
 { t: "acik", ar: "تَدْريبٌ (٢): أَجِبْ مِمّا سَمِعْتَ عَنِ الأَسْئِلَةِ التّالِيَةِ بِاخْتِصارٍ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["ما عَدَدُ السُّوَرِ الَّتي سُمِّيَتْ بِأَسْماءِ الحَيَواناتِ؟", "ذُكِرَتْ في الكَلامِ سِتُّ سُوَرٍ: البَقَرَةُ، وَالنَّمْلُ، وَالنَّحْلُ، وَالعَنْكَبوتُ، وَالأَنْعامُ، وَالفيلُ.", "How many suras are named after animals?", "The recording says ‘some suras’ and counts six; there are other suras in the Qur'an too (e.g. al-ʿĀdiyāt)."],
  ["ما الحَيَواناتُ الَّتي تَعيشُ في البَرِّ؟", "كَالأَفْيالِ وَالفَراشاتِ.", "Which are the animals that live on land?"],
  ["هَلْ يَعْرِفُ العُلَماءُ عَدَدَ الحَيَواناتِ المَوْجودَةِ عَلى الأَرْضِ؟", "لا، لا يَعْرِفونَ عَدَدَها.", "Do scholars know the number of animals on earth?"],
  ["هَلْ تَخْتَلِفُ الحَيَواناتُ في حَرَكَتِها؟", "نَعَمْ؛ فَمِنْها ما يَمْشي، وَما يَزْحَفُ، وَما يَطيرُ، وَما يَسْبَحُ.", "Do animals differ in their movement?"],
  ["هَلِ الحَيَواناتُ الأَليفَةُ أَكْثَرُ أَمِ الحَيَواناتُ المُتَوَحِّشَةُ؟", "الحَيَواناتُ المُتَوَحِّشَةُ أَكْثَرُ.", "Are domestic animals more, or wild animals?"]] },
 { t: "secim", ar: "تَدْريبٌ (٣): اخْتَرِ الجَوابَ الصَّحيحَ", ogeler: [
  ["مِنْ أَسْماءِ الحَيَواناتِ الَّتي وَرَدَتْ في القُرْآنِ الكَريمِ وَلَمْ تَرِدْ في النَّصِّ…", "الكَلْبُ", ["البَقَرَةُ", "النَّمْلُ"], "Among animal names that occur in the Qur'an but not in the text …"],
  ["مِنَ الحَيَواناتِ الوَحْشِيَّةِ الَّتي لَمْ تَرِدْ في النَّصِّ…", "الذِّئْبُ", ["الأَسَدُ", "النَّمِرُ"], "Among wild animals not mentioned in the text …"],
  ["مِنَ الحَيَواناتِ الَّتي تُسْتَعْمَلُ في النَّقْلِ كَما جاءَ في النَّصِّ…", "الجِمالُ", ["الأُسودُ", "الأَفْيالُ"], "According to the text, among animals used for carrying …"]] },
 { t: "dinle", s: "l67b", ar: "القِسْمُ الثّاني: اخْتِلافُ الحَيَواناتِ", aciklama: "Animals by number of legs and habitat; protecting animals in Islam. Listen first, then answer the questions.", metin: [
  ["يَخْتَلِفُ عَدَدُ أَرْجُلِ الحَيَواناتِ؛ فَمِنْها ما لَهُ رِجْلانِ كَالطُّيورِ، وَمِنْها ما لَهُ أَرْبَعُ أَرْجُلٍ كَالأَبْقارِ وَالقِطَطِ، وَمِنْها ما لَها سِتُّ أَرْجُلٍ كَالحَشَراتِ، وَمِنْها ما لَها ثَماني أَرْجُلٍ كَالعَناكِبِ، وَهُناكَ حَيَواناتٌ لَها مِئاتُ الأَرْجُلِ، وَمِنَ الحَيَواناتِ ما لَيْسَ لَهُ أَرْجُلٌ كَالأَسْماكِ.", "Animals differ in the number of legs: there are two-legged ones like birds, four-legged like cattle and cats, six-legged like insects, eight-legged like spiders; there are animals with hundreds of legs; and those with no legs at all like fish."],
  ["يَخْتَلِفُ المَكانُ الَّذي تَعيشُ فيهِ الحَيَواناتُ؛ فَهُناكَ حَيَواناتُ المَنْزِلِ كَالقِطَطِ وَالكِلابِ، وَحَيَواناتُ المَزْرَعَةِ كَالأَبْقارِ وَالأَرانِبِ، وَحَيَواناتُ الجِبالِ كَالطُّيورِ وَالأَغْنامِ الجَبَلِيَّةِ، وَحَيَواناتُ الغابَةِ كَالقُرودِ وَالأُسودِ.", "Animals differ in where they live: there are house animals like the cat and dog, farm animals like cattle and rabbits, mountain animals like birds and mountain goats, and forest animals like monkeys and lions."],
  ["الحَيَواناتُ أُمَمٌ كَالنّاسِ، لَها نِظامُ حَياةٍ، وَلُغَةٌ تَتَفاهَمُ بِها، وَفي الحَيَواناتِ خَيْرٌ كَثيرٌ لِلْإِنْسانِ؛ فَعَلى الإِنْسانِ أَنْ يُحافِظَ عَلى الحَيَواناتِ مِنْ أَجْلِ الأَجْيالِ القادِمَةِ. وَيَدْعو الإِسْلامُ إِلى الرِّفْقِ بِالحَيَوانِ، وَعَدَمِ الإِسْرافِ في اسْتِهْلاكِهِ، وَيَنْهى عَنِ العَبَثِ وَالتَّمْثيلِ بِهِ، وَتَوَعَّدَ اللهُ مَنْ يُمَثِّلُ بِهِ أَنْ يُمَثَّلَ بِهِ يَوْمَ القِيامَةِ.", "Animals are communities like humans; they have a way of life and a language they understand. There is much good for man in animals; man must protect animals for future generations. Islam calls to kindness to animals and not wasting them; it forbids playing with them and harming them and cutting their limbs; God has threatened one who mutilates an animal with the same on the Day of Resurrection."],
  ["وَقَدْ مَرَّ الرَّسولُ ﷺ بِحِمارٍ كَواهُ صاحِبُهُ بِالنّارِ في وَجْهِهِ، فَقالَ: «لَعَنَ اللهُ الَّذي وَسَمَهُ» (رَواهُ مُسْلِمٌ). وَيَمْنَعُ الإِسْلامُ ضَرْبَ الحَيَوانِ، أَوْ تَحْميلَهُ فَوْقَ طاقَتِهِ، أَوْ رُكوبَهُ إِذا كانَ مَريضًا، وَيُحَرِّمُ الإِسْلامُ أَكْلَ الحَيَواناتِ المَيِّتَةِ، وَلَحْمَ الخِنْزيرِ.", "The Messenger of God ﷺ passed by a donkey whose owner had branded its face with fire and said, “May God curse the one who branded it” (reported by Muslim). Islam forbids beating an animal, loading it beyond its strength or riding it when it is ill; it forbids eating carrion and pork."]],
  not: "The text was transcribed from the recording; the book contains only the questions." },
 { t: "acik", ar: "تَدْريبٌ (١): مَثِّلْ لِما يَلي مِمّا اسْتَمَعْتَ إِلَيْهِ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["حَيَوانٌ لَهُ أَرْبَعُ أَرْجُلٍ.", "البَقَرَةُ، القِطُّ.", "four-legged animal"], ["حَيَوانٌ لَيْسَ لَهُ أَرْجُلٌ.", "السَّمَكُ.", "legless animal"], ["حَيَوانٌ لَهُ ثَماني أَرْجُلٍ.", "العَنْكَبوتُ.", "eight-legged animal"],
  ["حَيَوانٌ لَهُ رِجْلانِ.", "الطّائِرُ.", "two-legged animal"], ["حَيَوانٌ لَهُ سِتُّ أَرْجُلٍ.", "الحَشَراتُ (كَالنَّمْلَةِ وَالذُّبابَةِ).", "six-legged animal"]] },
 { t: "acik", ar: "تَدْريبٌ (٢): أَجِبْ مِمّا سَمِعْتَ عَنِ الأَسْئِلَةِ التّالِيَةِ بِاخْتِصارٍ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["لِماذا تَجِبُ المُحافَظَةُ عَلى الحَيَوانِ؟", "لِأَنَّ الحَيَواناتِ أُمَمٌ كَالنّاسِ، وَفيها خَيْرٌ كَثيرٌ لِلْإِنْسانِ، وَمِنْ أَجْلِ الأَجْيالِ القادِمَةِ.", "Why is protecting animals necessary?"],
  ["ما جَزاءُ مَنْ يُمَثِّلُ بِالحَيَوانِ؟", "تَوَعَّدَهُ اللهُ أَنْ يُمَثَّلَ بِهِ يَوْمَ القِيامَةِ.", "What is the punishment of one who mutilates an animal?"],
  ["ما الحَيَوانُ الَّذي يَحْرُمُ أَكْلُهُ عَلى المُسْلِمِ؟", "الحَيَواناتُ المَيِّتَةُ، وَالخِنْزيرُ.", "Which animal is forbidden for a Muslim to eat?"],
  ["كَيْفَ يُعامِلُ المُسْلِمُ الحَيَوانَ؟", "يَرْفُقُ بِهِ، وَلا يُسْرِفُ في اسْتِهْلاكِهِ، وَلا يَعْبَثُ بِهِ، وَلا يَضْرِبُهُ، وَلا يُحَمِّلُهُ فَوْقَ طاقَتِهِ، وَلا يَرْكَبُهُ إِذا كانَ مَريضًا.", "How does a Muslim treat an animal?"],
  ["هَلْ لِلْحَيَوانِ لُغَةٌ؟ وَضِّحْ ذلِكَ.", "نَعَمْ، الحَيَواناتُ أُمَمٌ لَها نِظامُ حَياةٍ وَلُغَةٌ تَتَفاهَمُ بِها.", "Does an animal have a language? Explain."]] },
 { t: "acik", ar: "تَدْريبٌ (٣): اذْكُرْ حَيَوانًا واحِدًا في كُلِّ مَرَّةٍ مِمّا سَمِعْتَ في النَّصِّ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["مِنَ الحَيَواناتِ المَنْزِلِيَّةِ…", "القِطُّ (أَوِ الكَلْبُ).", "from house animals"], ["مِنْ حَيَواناتِ المَزْرَعَةِ…", "البَقَرَةُ (أَوِ الأَرْنَبُ).", "from farm animals"],
  ["مِنْ حَيَواناتِ الجِبالِ…", "الطُّيورُ (أَوِ الأَغْنامُ الجَبَلِيَّةُ).", "from mountain animals"], ["مِنْ حَيَواناتِ الغابَةِ…", "القِرْدُ (أَوِ الأَسَدُ).", "from forest animals"]] }
]},
// ---------------- DERS 68 ----------------
{ no: 68, kisa: "التَّعْبيرُ", ar: "التَّعْبيرُ الشَّفَهِيُّ وَالكِتابِيُّ", tr: "Oral and written expression", ozet: "Speaking about animals, describing pictures, giving advice and writing.", bloklar: [
 { t: "acik", ar: "أَوَّلًا: التَّعْبيرُ الشَّفَهِيُّ — تَدْريبٌ (١): تَبادَلِ الأَسْئِلَةَ وَالأَجْوِبَةَ مَعَ زَميلِكَ", aciklama: "A pair activity; then look at the sample answer.", ogeler: [
  ["ما الحَيَواناتُ النّافِعَةُ لِلْإِنْسانِ؟", "البَقَرُ، وَالغَنَمُ، وَالإِبِلُ، وَالخَيْلُ، وَالدَّجاجُ، وَالنَّحْلُ.", "Which animals are useful to man?"], ["ما الحَيَواناتُ الضّارَّةُ بِالإِنْسانِ؟", "الأَفاعي، وَالعَقارِبُ، وَالفِئْرانُ، وَالبَعوضُ.", "Which animals are harmful to man?"],
  ["ما الحَيَوانُ الَّذي تُحِبُّهُ؟ لِماذا؟", "أُحِبُّ الحِصانَ؛ لِأَنَّهُ جَميلٌ وَقَوِيٌّ وَوَفِيٌّ.", "Which animal do you like? Why?"], ["ما الحَيَوانُ الَّذي لا تُحِبُّهُ؟ لِماذا؟", "لا أُحِبُّ الفَأْرَ؛ لِأَنَّهُ يَنْقُلُ الأَمْراضَ وَيُفْسِدُ الطَّعامَ.", "Which animal do you not like? Why?"],
  ["هَلْ تُرَبّي حَيَوانًا / حَيَواناتٍ في بَيْتِكَ / مَزْرَعَتِكَ؟ لِماذا؟", "نَعَمْ، أُرَبّي قِطَّةً؛ لِأَنَّها لَطيفَةٌ وَنَظيفَةٌ.", "Do you keep animals in your house / farm? Why?"], ["كَيْفَ تُعامِلُ الحَيَوانَ؟ لِماذا؟", "أُعامِلُهُ بِرِفْقٍ؛ لِأَنَّ الرَّحْمَةَ بِهِ تُدْخِلُ الجَنَّةَ.", "How do you treat animals? Why?"]] },
 { t: "resim", ar: "تَدْريبٌ (٢): تَبادَلْ وَصْفَ الحَيَواناتِ مَعَ زَميلِكَ", aciklama: "Describe each picture in a few sentences; then look at the example.", resimler: [
  ["deve", "هذا جَمَلٌ بارِكٌ عَلى الأَرْضِ، عَلى ظَهْرِهِ سَرْجٌ مُلَوَّنٌ، وَهُوَ سَفينَةُ الصَّحْراءِ، يَصْبِرُ عَلى العَطَشِ وَيَحْمِلُ الأَثْقالَ.", "The camel: Knelt on the ground, with a coloured saddle on its back; it is the ship of the desert."],
  ["at", "هذا حِصانٌ جَميلٌ يَجْري في المَرْعى، لَوْنُهُ بُنِّيٌّ وَشَعْرُهُ أَشْقَرُ، وَهُوَ سَريعٌ وَقَوِيٌّ.", "The horse: A fine horse running in the pasture; fast and strong."],
  ["fil", "هذا فيلٌ ضَخْمٌ، لَهُ خُرْطومٌ طَويلٌ وَأُذُنانِ كَبيرَتانِ، وَهُوَ أَكْبَرُ حَيَواناتِ البَرِّ.", "The elephant: A huge elephant with a long trunk and big ears; the largest land animal."]] },
 { t: "resim", ar: "تَدْريبٌ (٣): بِمَ تَنْصَحُ هؤُلاءِ؟", aciklama: "A pair activity: give advice to the person in each picture; then look at the example.", resimler: [
  ["araba", "أَنْصَحُهُمْ أَلّا يَرْكَبوا العَرَبَةَ كُلُّهُمْ؛ فَالحِمارُ صَغيرٌ لا يَسْتَطيعُ أَنْ يَحْمِلَ كُلَّ هذا العَدَدِ.", "People crowding onto a donkey cart: Not all should ride; the donkey cannot carry so many people."],
  ["yuk", "أَنْصَحُ صاحِبَ العَرَبَةِ أَنْ يُخَفِّفَ الحِمْلَ؛ فَالرَّسولُ ﷺ نَهى عَنْ تَحْميلِ الحَيَوانِ أَكْثَرَ مِمّا يَسْتَطيعُ.", "The overloaded cart: Lighten the load; the Prophet ﷺ forbade loading an animal beyond its strength."],
  ["dovme", "أَنْصَحُهُ أَلّا يَضْرِبَ الحِصانَ؛ فَالحَيَوانُ لا يُضْرَبُ ضَرْبًا قَوِيًّا، وَالقَسْوَةُ عَلَيْهِ تُدْخِلُ النّارَ.", "The man beating the horse: Do not beat; an animal is not struck hard, and harshness to it admits to Hell."]] },
 { t: "acik", ar: "ثانِيًا: التَّعْبيرُ الكِتابِيُّ", aciklama: "Write in your notebook; then look at the sample text.", ogeler: [
  ["تَدْريبٌ (١): أَعِدِ الاسْتِماعَ إِلى نَصِّ فَهْمِ المَسْموعِ (القِسْمُ الأَوَّلُ وَالثّاني) وَقُمْ بِتَلْخيصِهِ، مُسْتَعينًا بِالعَناصِرِ: الحَيَوانُ في القُرْآنِ الكَريمِ، أَهَمِّيَّةُ الحَيَوانِ في حَياةِ الإِنْسانِ، أَنْواعُ الحَيَوانِ، عالَمُ الحَيَوانِ وَلُغاتُهُ، حِمايَةُ الحَيَوانِ وَالحِفاظُ عَلَيْهِ.", "تَحَدَّثَ القُرْآنُ الكَريمُ عَنِ الحَيَوانِ في كَثيرٍ مِنْ سُوَرِهِ، وَسُمِّيَتْ بَعْضُ السُّوَرِ بِأَسْمائِهِ كَالبَقَرَةِ وَالنَّحْلِ وَالفيلِ. وَلِلْحَيَوانِ أَهَمِّيَّةٌ كَبيرَةٌ في حَياةِ الإِنْسانِ؛ فَهُوَ يَأْكُلُ لَحْمَهُ وَيَشْرَبُ لَبَنَهُ، وَيَلْبَسُ مِنْ صوفِهِ وَجِلْدِهِ، وَيَسْتَعْمِلُهُ في النَّقْلِ وَالزِّراعَةِ. وَالحَيَواناتُ أَنْواعٌ: مِنْها ما يَمْشي وَما يَزْحَفُ وَما يَطيرُ وَما يَسْبَحُ، وَمِنْها الضَّخْمُ وَالصَّغيرُ، وَالأَليفُ وَالوَحْشِيُّ، وَمِنْها ما يَعيشُ في البَرِّ أَوْ في الماءِ أَوْ فيهِما، وَتَخْتَلِفُ في عَدَدِ أَرْجُلِها وَفي أَماكِنِ عَيْشِها. وَالحَيَواناتُ أُمَمٌ مِثْلُنا، لَها نِظامُ حَياةٍ وَلُغَةٌ تَتَفاهَمُ بِها. لِذلِكَ يَجِبُ أَنْ نُحافِظَ عَلَيْها مِنْ أَجْلِ الأَجْيالِ القادِمَةِ، وَأَنْ نَرْفُقَ بِها كَما أَمَرَ الإِسْلامُ، فَلا نَعْبَثَ بِها وَلا نُمَثِّلَ بِها، وَلا نَضْرِبَها وَلا نُحَمِّلَها فَوْقَ طاقَتِها.", "Summarize the listening text."],
  ["تَدْريبٌ (٢): اكْتُبْ مَوْضوعًا بِعُنْوانِ: «الرِّفْقُ بِالحَيَوانِ» فيما لا يَقِلُّ عَنْ ٢٠٠ كَلِمَةٍ: التَّشابُهُ بَيْنَ عالَمِ الإِنْسانِ وَعالَمِ الحَيَوانِ، الرَّحْمَةُ بِالحَيَوانِ قَدْ تُدْخِلُ الجَنَّةَ، القَسْوَةُ عَلَيْهِ قَدْ تُدْخِلُ النّارَ، عَدَمُ تَحْميلِهِ فَوْقَ طاقَتِهِ، عَدَمُ ضَرْبِهِ ضَرْبًا مُؤْذِيًا، عَدَمُ إِرْهاقِهِ بِالعَمَلِ وَقْتًا طَويلًا، عَدَمُ تَعْذيبِهِ أَوْ قَتْلِهِ لِلَّعِبِ وَالتَّسْلِيَةِ، آدابُ الإِسْلامِ عِنْدَ ذَبْحِهِ، جَمْعِيّاتُ الرِّفْقِ بِالحَيَوانِ وَدَوْرُها.", "عالَمُ الحَيَوانِ يُشْبِهُ عالَمَ الإِنْسانِ؛ فَالحَيَوانُ يَشْعُرُ بِالجوعِ وَالعَطَشِ وَالأَلَمِ، وَقَدْ قالَ تَعالى: ﴿إِلَّا أُمَمٌ أَمْثَالُكُمْ﴾. وَالرَّحْمَةُ بِالحَيَوانِ قَدْ تُدْخِلُ صاحِبَها الجَنَّةَ، كَالرَّجُلِ الَّذي سَقى كَلْبًا فَغَفَرَ اللهُ لَهُ، وَالقَسْوَةُ عَلَيْهِ قَدْ تُدْخِلُ النّارَ، كَالمَرْأَةِ الَّتي حَبَسَتْ هِرَّةً حَتّى ماتَتْ. لِذلِكَ يَجِبُ أَلّا نُحَمِّلَ الحَيَوانَ فَوْقَ طاقَتِهِ، وَأَلّا نَضْرِبَهُ ضَرْبًا مُؤْذِيًا، وَأَلّا نُرْهِقَهُ بِالعَمَلِ وَقْتًا طَويلًا، فَقَدْ شَكا الجَمَلُ إِلى الرَّسولِ ﷺ أَنَّ صاحِبَهُ يُجيعُهُ وَيُتْعِبُهُ. وَلا يَجوزُ تَعْذيبُ الحَيَوانِ أَوْ قَتْلُهُ لِلَّعِبِ وَالتَّسْلِيَةِ، وَلا اتِّخاذُهُ هَدَفًا لِلرَّمْيِ. وَإِذا ذَبَحْنا الحَيَوانَ لِنَأْكُلَهُ، فَعَلَيْنا أَنْ نُحِدَّ السِّكّينَ، وَأَلّا نَذْبَحَهُ أَمامَ غَيْرِهِ، وَأَنْ نَتْرُكَهُ حَتّى يَبْرُدَ قَبْلَ السَّلْخِ. وَقَدْ عَرَفَتْ حَضارَتُنا أَوْقافًا لِعِلاجِ الحَيَواناتِ المَريضَةِ وَرِعايَةِ العاجِزَةِ مِنْها. وَفي عَصْرِنا ظَهَرَتْ جَمْعِيّاتٌ لِلرِّفْقِ بِالحَيَوانِ، تُعالِجُ الحَيَواناتِ الضّالَّةَ، وَتَمْنَعُ تَعْذيبَها، وَتَنْشُرُ الوَعْيَ بَيْنَ النّاسِ. فَما أَحْوَجَنا إِلى أَنْ نَتَخَلَّقَ بِأَخْلاقِ الإِسْلامِ في الرِّفْقِ بِكُلِّ مَخْلوقٍ!", "A piece of at least 200 words on “Kindness to Animals”."]] }
]},
// ---------------- DERS 69 ----------------
{ no: 69, kisa: "الإِمْلاءُ: الهَمَزاتُ (مُراجَعَةٌ)", ar: "الإِمْلاءُ: كِتابَةُ الهَمَزاتِ (مُراجَعَةٌ)", tr: "Spelling: the writing of hamzas (review)", ozet: "Hamza at the beginning, middle and end of a word: general review.", bloklar: [
 { t: "tablo", ar: "كِتابَةُ الهَمَزاتِ (مُراجَعَةٌ)", bas: ["المَوْضِعُ", "الحالَةُ", "أَمْثِلَةٌ"], satir: [
  ["أَوَّلَ الكَلِمَةِ", "وَصْلٌ (ا)", "اسْمٌ، اجْلِسْ"], ["أَوَّلَ الكَلِمَةِ", "قَطْعٌ: مَفْتوحَةٌ أَوْ مَضْمومَةٌ (أ)، مَكْسورَةٌ (إ)", "أَكَلَ، أُكِلَ، إِبِلٌ"],
  ["وَسَطَ الكَلِمَةِ", "عَلى نَبْرَةٍ: مَكْسورَةٌ أَوْ قَبْلَها كَسْرَةٌ", "رِئَةٌ، يَئِسَ"], ["وَسَطَ الكَلِمَةِ", "عَلى واوٍ: مَضْمومَةٌ أَوْ قَبْلَها ضَمَّةٌ", "مُؤْمِنٌ، هؤُلاءِ"], ["وَسَطَ الكَلِمَةِ", "عَلى أَلِفٍ أَوْ مُفْرَدَةً: مَفْتوحَةٌ قَبْلَها فَتْحَةٌ أَوْ ساكِنٌ", "رَأْسٌ، يَنْأى، قِراءَةٌ"],
  ["آخِرَ الكَلِمَةِ", "بَعْدَ كَسْرٍ (ئ) — بَعْدَ ضَمٍّ (ؤ) — بَعْدَ فَتْحٍ (أ) — بَعْدَ سُكونٍ (ء)", "قُرِئَ، لُؤْلُؤٌ، قَرَأَ، جُزْءٌ"]] },
 { t: "kural", ar: "تَذْكيرٌ: الهَمْزَةُ المُتَوَسِّطَةُ", metin: "القُوَّةُ تَبْدَأُ مِنَ الكَسْرَةِ، ثُمَّ الضَّمَّةِ، ثُمَّ الفَتْحَةِ: فَإِنْ كانَ قَبْلَ الهَمْزَةِ المُتَوَسِّطَةِ كَسْرَةٌ أَوْ كانَتْ مَكْسورَةً كُتِبَتْ عَلى نَبْرَةٍ، فَإِنْ لَمْ تَكُنْ كَذلِكَ وَكانَ قَبْلَها ضَمَّةٌ أَوْ هِيَ مَضْمومَةٌ كُتِبَتْ عَلى واوٍ، فَإِنْ كانَ قَبْلَها فَتْحَةٌ كُتِبَتْ عَلى أَلِفٍ. وَإِنْ كانَتْ مَفْتوحَةً وَقَبْلَها ساكِنٌ: فَإِنْ كانَ صامِتًا كُتِبَتْ عَلى أَلِفٍ (مَسْأَلَةٌ)، وَإِنْ كانَ أَلِفًا أَوْ واوًا كُتِبَتْ عَلى السَّطْرِ (تَساءَلَ، سَوْءَةٌ)، وَإِنْ كانَ ياءً كُتِبَتْ عَلى نَبْرَةٍ (هَيْئَةٌ، شَيْئًا).", tr: "Order of strength: kasra, ḍamma, fatḥa. A medial hamza is written on the nabra if it has kasra or the preceding letter has kasra, on a wāw if it has ḍamma or the one before has ḍamma, on an alif if the one before has fatḥa. If it has fatḥa and the one before is quiescent: if the quiescent is a sound letter, an alif (مَسْأَلَةٌ), if alif/wāw, on the line (تَساءَلَ، سَوْءَةٌ), if yāʾ, the nabra (هَيْئَةٌ، شَيْئًا)." },
 { t: "acik", ar: "تَدْريبٌ (١): حَوِّلِ الأَفْعالَ الماضِيَةَ الَّتي تَحْتَها خَطٌّ إِلى أَفْعالٍ مُضارِعَةٍ، وَغَيِّرْ ما يَلْزَمُ، بَعْدَ إِعادَةِ كِتابَةِ الجُمْلَةِ", aciklama: "First write it yourself; then look at the answer (pay attention to the writing of the hamza).", ogeler: [
  ["[[أُكِلَ]] الطَّعامُ لَيْلًا.", "يُؤْكَلُ الطَّعامُ لَيْلًا.", "The food was eaten at night → is eaten."], ["[[يَئِسَ]] المُذْنِبُ مِنَ النَّجاةِ.", "يَيْأَسُ المُذْنِبُ مِنَ النَّجاةِ.", "The sinner despaired of salvation → despairs."],
  ["[[أَمَّ]] النّاسَ في الصَّلاةِ عَلِيٌّ.", "يَؤُمُّ النّاسَ في الصَّلاةِ عَلِيٌّ.", "ʿAlī was the imam for people in prayer → is."], ["[[بُدِئَ]] الحَفْلُ بِالتِّلاوَةِ.", "يُبْدَأُ الحَفْلُ بِالتِّلاوَةِ.", "The ceremony was begun with recitation → is begun."],
  ["[[خَبَّأَ]] اللِّصُّ المالَ في صُنْدوقٍ.", "يُخَبِّئُ اللِّصُّ المالَ في صُنْدوقٍ.", "The thief hid the money in a chest → hides."], ["عُمّالُ المَناجِمِ [[سَئِموا]] مِنْ أَعْمالِهِمْ تَحْتَ الأَرْضِ.", "عُمّالُ المَناجِمِ يَسْأَمونَ مِنْ أَعْمالِهِمْ تَحْتَ الأَرْضِ.", "The miners grew tired of their underground work → grow tired."]] },
 { t: "acik", ar: "تَدْريبٌ (٢): ضَعْ ضَميرَ المُتَكَلِّمينَ «نا» مَكانَ «الأُمَّة» فيما يَلي، ثُمَّ أَعِدْ كِتابَةَ الجُمْلَةِ", aciklama: "First write it yourself; then look at the answer (pay attention to how the hamza changes with the case ending).", ogeler: [
  ["عُلَماءُ الأُمَّةِ هُمْ سَنَدُها في الشَّدائِدِ.", "عُلَماؤُنا هُمْ سَنَدُنا في الشَّدائِدِ.", "Our scholars are our support in hard days."], ["لا يَزالُ الشَّبابُ بِخَيْرٍ ما اتَّبَعوا عُلَماءَ الأُمَّةِ.", "لا يَزالُ الشَّبابُ بِخَيْرٍ ما اتَّبَعوا عُلَماءَنا.", "Young people are on good as long as they follow our scholars."],
  ["اقْرَأْ كُتُبَ عُلَماءِ الأُمَّةِ النّاصِحينَ.", "اقْرَأْ كُتُبَ عُلَمائِنا النّاصِحينَ.", "Read the books of our advising scholars."], ["تَرْبِيَةُ أَبْناءِ الأُمَّةِ مَسْؤولِيَّةُ التَّرْبَوِيّينَ.", "تَرْبِيَةُ أَبْنائِنا مَسْؤولِيَّةُ التَّرْبَوِيّينَ.", "The upbringing of our children is the responsibility of educators."],
  ["مَنْ أَحَبَّ أَبْناءَ الأُمَّةِ أَحَبَّ لَهُمُ الخَيْرَ.", "مَنْ أَحَبَّ أَبْناءَنا أَحَبَّ لَهُمُ الخَيْرَ.", "One who loves our children wishes good for them."], ["أَبْناءُ الأُمَّةِ ذُخْرُها في المُسْتَقْبَلِ.", "أَبْناؤُنا ذُخْرُنا في المُسْتَقْبَلِ.", "Our children are our future treasure."],
  ["بِناءُ الأُمَّةِ يَتِمُّ بِبِناءِ شَبابِها.", "بِناؤُنا يَتِمُّ بِبِناءِ شَبابِنا.", "Our development comes by bringing up our young people."], ["إِنَّ بِناءَ الأُمَّةِ مَسْؤولِيَّةٌ كَبيرَةٌ.", "إِنَّ بِناءَنا مَسْؤولِيَّةٌ كَبيرَةٌ.", "Our development is a great responsibility."],
  ["لِبِناءِ الأُمَّةِ أَوْلَوِيَّةٌ في التَّرْبِيَةِ.", "لِبِنائِنا أَوْلَوِيَّةٌ في التَّرْبِيَةِ.", "Our development has priority in education."], ["أُمَراءُ الأُمَّةِ مُطاعونَ ما أَطاعوا اللهَ.", "أُمَراؤُنا مُطاعونَ ما أَطاعوا اللهَ.", "Our rulers are obeyed as long as they obey God."],
  ["أُمِرْنا بِطاعَةِ أُمَراءِ الأُمَّةِ وَأَهْلِ العِلْمِ فيها.", "أُمِرْنا بِطاعَةِ أُمَرائِنا وَأَهْلِ العِلْمِ فينا.", "We were commanded to obey our rulers and the people of knowledge among us."], ["لَيْتَ أُمَراءَ الأُمَّةِ يَتَّفِقونَ مَعَ العُلَماءِ.", "لَيْتَ أُمَراءَنا يَتَّفِقونَ مَعَ العُلَماءِ.", "Would that our rulers would agree with the scholars."]],
  not: "The final hamza falls in the middle with ‘نا’: if ḍamma, on و (عُلَماؤُنا), if fatḥa, on the line (عُلَماءَنا), if kasra, the nabra (عُلَمائِنا)." }
]},
// ---------------- DERS 70 ----------------
{ no: 70, kisa: "لا النّافِيَةُ لِلْجِنْسِ", ar: "قَواعِدُ اللُّغَةِ (ب): (لا) النّافِيَةُ لِلْجِنْسِ", tr: "Grammar: the generic negating lā", ozet: "The lā that negates the predicate of all individuals of the genus; the three conditions for its governing like إِنَّ.", bloklar: [
 { t: "tablo", ar: "الأَمْثِلَةُ: ادْرُسْ وَتَأَمَّلْ", bas: ["", "الأَمْثِلَةُ"], satir: [
  ["أ (عامِلَةٌ)", "لا فَرَحَ دائِمٌ. — لا شَجَرَةَ زَيْتونٍ مُثْمِرَةٌ. — ﴿ذَٰلِكَ الْكِتَابُ لَا رَيْبَ﴾ — ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ﴾"],
  ["ب (غَيْرُ عامِلَةٍ)", "تَعِبَ المُسافِرُ بِلا فائِدَةٍ. — لا الطُّلّابُ حاضِرونَ وَلا المُدَرِّسونَ. — ﴿لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنْزَفُونَ﴾"]] },
 { t: "kural", ar: "الشَّرْحُ", metin: "تَأَمَّلْ «لا» في الأَمْثِلَةِ السّابِقَةِ تَجِدْها نَفَتِ الحُكْمَ عَنْ جَميعِ أَفْرادِ الجِنْسِ؛ وَلِذا تُسَمّى «نافِيَةَ الجِنْسِ». وَفي القائِمَةِ (أ) تَجِدُ أَنَّ «لا» عَمِلَتْ عَمَلَ «إِنَّ»، وَذلِكَ بَعْدَ اسْتيفاءِ شُروطِ عَمَلِها. وَفي القائِمَةِ (ب) تَجِدُ أَنَّ «لا» لَمْ تَعْمَلْ عَمَلَ «إِنَّ»؛ لِأَنَّها فَقَدَتْ بَعْضَ شُروطِ عَمَلِها: فَهِيَ في المِثالِ الأَوَّلِ مُتَّصِلَةٌ بِحَرْفِ الجَرِّ «الباءِ»، وَفي المِثالِ الثّاني لَمْ تَعْمَلْ وَكُرِّرَتْ لِأَنَّ اسْمَها مَعْرِفَةٌ، وَفي المِثالِ الثّالِثِ فُصِلَ بَيْنَها وَبَيْنَ اسْمِها «غَوْلٌ» بِفاصِلٍ هُوَ «فيها» وَكُرِّرَتْ؛ وَلِذلِكَ لَمْ تَعْمَلْ.", tr: "The لا in the examples negates the ruling from all individuals of the genus: the generic negating lā. In (أ) it works like إِنَّ because its conditions are complete. In (ب) it does not work because some conditions are lacking: in example 1 it took a preposition (بِـ); in example 2 its noun is definite and repeated; in example 3 فيها came between it and its noun and it is repeated." },
 { t: "kural", ar: "القاعِدَةُ", metin: "(لا) النّافِيَةُ لِلْجِنْسِ، هِيَ الَّتي يَكونُ فيها الخَبَرُ مَنْفِيًّا عَنْ جَميعِ أَفْرادِ الجِنْسِ. وَتَعْمَلُ عَمَلَ «إِنَّ»: فَتَنْصِبُ المُبْتَدَأَ اسْمًا لَها، وَتَرْفَعُ الخَبَرَ خَبَرًا لَها، بِثَلاثَةِ شُروطٍ: ١- أَلّا يَدْخُلَ عَلَيْها جارٌّ (حَرْفُ جَرٍّ). ٢- أَنْ يَكونَ اسْمُها وَخَبَرُها نَكِرَتَيْنِ. ٣- أَلّا يُفْصَلَ اسْمُها عَنْها بِفاصِلٍ. فَإِنْ دَخَلَ عَلَيْها جارٌّ بَطَلَ عَمَلُها، وَإِنْ فُقِدَ الشَّرْطانِ الآخَرانِ بَطَلَ عَمَلُها وَلَزِمَ تَكْرارُها.", tr: "The generic negating lā is the lā that negates the predicate from all individuals of the genus. It works like إِنَّ (puts the subject in the accusative as its noun and the predicate in the nominative as its predicate); with three conditions: 1) no preposition before it; 2) its noun and predicate are indefinite; 3) nothing comes between it and its noun. If a preposition comes, its government is void; if the other two conditions are lacking, its government is void and it must be repeated." },
 { t: "acik", ar: "تَدْريبٌ (١): بَيِّنْ «لا» العامِلَةَ عَمَلَ إِنَّ وَالمُهْمَلَةَ، وَبَيِّنْ سَبَبَ إِهْمالِها فيما يَلي", aciklama: "First think for yourself; then look at the answer.", ogeler: [
  ["﴿وَلَوْ تَرَىٰ إِذْ فَزِعُوا فَلَا فَوْتَ﴾", "عامِلَةٌ (فَوْتَ: اسْمُها مَبْنِيٌّ عَلى الفَتْحِ).", "When they are seized by fear there is no escape."], ["﴿قَالُوا لَا ضَيْرَ إِنَّا إِلَىٰ رَبِّنَا مُنْقَلِبُونَ﴾", "عامِلَةٌ.", "No harm; we shall return to our Lord."],
  ["«لا أَحَدَ أَعْلَمُ مِنَ اللهِ».", "عامِلَةٌ.", "There is none more knowledgeable than God."], ["«لا صَلاةَ لِمَنْ لا وُضوءَ لَهُ».", "عامِلَتانِ.", "There is no prayer for one who has no ablution."],
  ["«لا إيمانَ لِمَنْ لا أَمانَةَ لَهُ».", "عامِلَتانِ.", "There is no faith for one who has no trust."], ["«لا حَسَدَ إِلّا في اثْنَتَيْنِ».", "عامِلَةٌ.", "There is envy only in two things."],
  ["لا حَوْلَ وَلا قُوَّةَ إِلّا بِاللهِ.", "عامِلَتانِ.", "There is no might and no power except with God."], ["جِئْتُ بِلا زادٍ.", "مُهْمَلَةٌ؛ لِدُخولِ حَرْفِ الجَرِّ عَلَيْها.", "I came without provisions."],
  ["لا زَيْدٌ في الدّارِ وَلا عَمْرٌو.", "مُهْمَلَةٌ؛ لِأَنَّ اسْمَها مَعْرِفَةٌ، وَلِذلِكَ كُرِّرَتْ.", "Neither Zayd is at home nor ʿAmr."]] },
 { t: "acik", ar: "تَدْريبٌ (٢): اجْعَلْ كُلَّ كَلِمَةٍ مِنَ الكَلِماتِ «خَيْر - دار - عَمَل - عِلْم - شَرّ» اسْمًا لِـ«لا» النّافِيَةِ لِلْجِنْسِ عامِلَةً مَرَّةً وَمُهْمَلَةً أُخْرى", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["خَيْر", "عامِلَةٌ: لا خَيْرَ في الكَذِبِ. — مُهْمَلَةٌ: لا في الكَذِبِ خَيْرٌ وَلا بَرَكَةٌ.", "good"], ["دار", "عامِلَةٌ: لا دارَ مَهْجورَةٌ في قَرْيَتِنا. — مُهْمَلَةٌ: لا الدّارُ واسِعَةٌ وَلا الحَديقَةُ.", "house"],
  ["عَمَل", "عامِلَةٌ: لا عَمَلَ أَفْضَلُ مِنَ الصَّلاةِ في وَقْتِها. — مُهْمَلَةٌ: رَجَعَ بِلا عَمَلٍ.", "job, work"], ["عِلْم", "عامِلَةٌ: لا عِلْمَ نافِعٌ بِلا عَمَلٍ. — مُهْمَلَةٌ: لا عِنْدَهُ عِلْمٌ وَلا أَدَبٌ.", "science"],
  ["شَرّ", "عامِلَةٌ: لا شَرَّ في الصِّدْقِ. — مُهْمَلَةٌ: لا الشَّرُّ نافِعٌ وَلا الكَذِبُ.", "evil"]] },
 { t: "siniflandir", ar: "تَدْريبٌ (٣): مَيِّزْ في الجُمَلِ التّالِيَةِ «لا» النّافِيَةَ لِلْجِنْسِ مِنْ «لا» النّافِيَةِ لِلْوَحْدَةِ", soru: "The kind of لا?", gruplar: ["نافِيَةٌ لِلْجِنْسِ", "نافِيَةٌ لِلْوَحْدَةِ"], ogeler: [
  ["لا مُدَرِّسٌ حاضِرًا بَلْ مُدَرِّسانِ.", 1], ["لا عَمَلَ خَيْرٍ ضائِعٌ.", 0], ["لا مَكْتَبَةٌ في المَدينَةِ بَلْ مَكْتَباتٌ.", 1], ["لا طالِبَ في الفَصْلِ.", 0], ["لا حَسودَ مُسْتَريحٌ.", 0]],
  not: "The lā of negation of oneness works like ليس and negates a single individual; therefore one can say ‘بَلْ مُدَرِّسانِ’ (rather two teachers). In the book the predicate of sentence 1 is written nominative; in the government of ليس it is accusative (حاضِرًا)." },
 { t: "acik", ar: "تَدْريبٌ (٤): ضَعِ اسْمًا مُناسِبًا لِـ«لا» النّافِيَةِ لِلْجِنْسِ في الفَراغِ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["لا … نافِعٌ.", "لا جَهْلَ نافِعٌ.", "No ignorance is beneficial."], ["لا … مَذْمومٌ.", "لا كَريمَ مَذْمومٌ.", "No generous person is blamed."], ["لا … في السّوقِ.", "لا زِحامَ في السّوقِ.", "There is no crowd at all in the market."],
  ["لا … والِدَيْهِ مُوَفَّقٌ.", "لا عاقًّا والِدَيْهِ مُوَفَّقٌ.", "No one who is disobedient to his parents will succeed.", "عاقًّا والِدَيْهِ: accusative with tanwīn because it is a noun resembling an annexation (shibh muḍāf)."], ["لا … اليَوْمَ.", "لا دِراسَةَ اليَوْمَ.", "There are no lessons today."],
  ["لا … أَفْضَلُ مِنَ الكِتابِ.", "لا صَديقَ أَفْضَلُ مِنَ الكِتابِ.", "There is no friend better than the book."], ["لا … في الماءِ.", "لا تَلَوُّثَ في الماءِ.", "There is no pollution at all in the water."], ["لا … في الفَصْلِ.", "لا طالِبَ في الفَصْلِ.", "There are no students in the class."],
  ["لا … دائِمٌ.", "لا شَيْءَ دائِمٌ.", "Nothing is lasting."], ["لا … مُحْتَرَمونَ.", "لا كاذِبينَ مُحْتَرَمونَ.", "No liar is respected."], ["لا … في الغُرْفَةِ.", "لا رَجُلَ في الغُرْفَةِ.", "There is no man in the room."],
  ["لا … في السَّماءِ.", "لا سَحابَ في السَّماءِ.", "There is no cloud in the sky."]] },
 { t: "acik", ar: "تَدْريبٌ (٥): أَعِدِ الجُمَلَ التّالِيَةَ بِحَيْثُ تَكونُ «لا» غَيْرَ عامِلَةٍ، وَغَيِّرْ ما يَلْزَمُ", aciklama: "First write it yourself; then look at the example (a separation, a definite noun or a preposition).", ogeler: [
  ["لا مَذْمومَ بَيْنَنا.", "لا بَيْنَنا مَذْمومٌ وَلا حاسِدٌ.", "There is no one blamed among us."], ["لا طالِبَ اليَوْمَ حاضِرٌ.", "لا الطّالِبُ حاضِرٌ اليَوْمَ وَلا المُدَرِّسُ.", "No student came today."],
  ["لا ظالِمَ مَحْبوبٌ.", "لا الظّالِمُ مَحْبوبٌ وَلا المُعْتَدي.", "No oppressor is loved."], ["لا بَرَكَةَ في حَياةٍ مَعَ الذُّلِّ.", "لا في حَياةِ الذُّلِّ بَرَكَةٌ وَلا راحَةٌ.", "There is no blessing in a life of abasement."],
  ["لا بَأْسَ عَلَيْكَ.", "لا عَلَيْكَ بَأْسٌ وَلا حَرَجٌ.", "Nothing will happen to you."], ["لا شاهِدَ زورٍ مُقَدَّرٌ.", "لا شاهِدُ الزّورِ مُقَدَّرٌ وَلا صاحِبُهُ.", "A lying witness is not valued."],
  ["لا بَيْتَ عِزٍّ مَكْروهٌ.", "لا بَيْتُ العِزِّ مَكْروهٌ وَلا أَهْلُهُ.", "A house of honour is not something disapproved."], ["لا نُجومَ في السَّماءِ.", "لا في السَّماءِ نُجومٌ وَلا قَمَرٌ.", "There is no star in the sky."],
  ["لا حَيَّ خالِدٌ.", "لا الإِنْسانُ خالِدٌ وَلا الحَيَوانُ.", "No living being is immortal."], ["لا حارِسَ في المَبْنى.", "لا في المَبْنى حارِسٌ وَلا بَوّابٌ.", "There is no guard in the building."],
  ["لا خَيْرَ في تارِكِ الصَّلاةِ.", "لا في تارِكِ الصَّلاةِ خَيْرٌ وَلا بَرَكَةٌ.", "There is no good in one who abandons prayer."], ["لا مَكْتَبَةَ في البَيْتِ.", "لا في البَيْتِ مَكْتَبَةٌ وَلا كُتُبٌ.", "There is no library at all in the house."]],
  not: "When a separation comes in or the noun is definite, لا must be repeated; therefore a second ‘وَلا …’ was added to the answers." }
]}
];
